def _safe_key_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    action = str(data.get("key_action") or planned_input.get("action") or "").strip()
    label = {
        "escape": "Escape",
        "tab": "Tab",
        "shift_tab": "Shift+Tab",
        "arrow_up": "上箭头",
        "arrow_down": "下箭头",
        "arrow_left": "左箭头",
        "arrow_right": "右箭头",
        "home": "Home",
        "end": "End",
        "page_up": "Page Up",
        "page_down": "Page Down",
        "show_desktop": "显示桌面",
    }.get(action, "")
    try:
        repeat_count = int(data.get("repeat_count") or planned_input.get("repeat_count") or 1)
    except (TypeError, ValueError):
        repeat_count = 1
    if not label:
        return ""
    if action == "show_desktop":
        return "已显示桌面。"
    suffix = "" if repeat_count == 1 else f"（{repeat_count} 次）"
    return f"已按{label}{suffix}。"


def _safe_scroll_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    direction = str(data.get("direction") or planned_input.get("direction") or "").strip().lower()
    label = {"down": "向下", "up": "向上"}.get(direction, "")
    try:
        pages = int(data.get("pages") or planned_input.get("pages") or 1)
    except (TypeError, ValueError):
        pages = 1
    if not label:
        return ""
    return f"已{label}滚动前台界面（{pages} 页）。"


def _system_volume_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    action = str(data.get("requested_action") or planned_input.get("action") or "").strip()
    level = data.get("level")
    muted = data.get("muted")
    old_level = data.get("old_level")
    try:
        level_text = f"{int(level)}%"
    except (TypeError, ValueError):
        level_text = ""
    try:
        old_level_text = f"{int(old_level)}%"
    except (TypeError, ValueError):
        old_level_text = ""
    if action == "status":
        if level_text:
            return f"当前系统音量是 {level_text}{'，已静音' if muted else ''}。"
        return ""
    if action == "set" and level_text:
        return f"已把系统音量调到 {level_text}。"
    if action == "up" and old_level_text and level_text:
        return f"已把系统音量从 {old_level_text} 调高到 {level_text}。"
    if action == "down" and old_level_text and level_text:
        return f"已把系统音量从 {old_level_text} 调低到 {level_text}。"
    if action == "mute":
        return "已将系统音量静音。"
    if action == "unmute":
        return f"已取消系统静音{f'，当前音量 {level_text}' if level_text else ''}。"
    return ""


def _system_brightness_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    action = str(data.get("requested_action") or planned_input.get("action") or "").strip()
    try:
        step = int(data.get("step") or planned_input.get("step") or 2)
    except (TypeError, ValueError):
        step = 2
    suffix = "" if step <= 1 else f"（{step} 格）"
    if action == "up":
        return f"已调高屏幕亮度{suffix}。"
    if action == "down":
        return f"已调低屏幕亮度{suffix}。"
    return ""


def _clipboard_write_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    length = data.get("text_length")
    if not isinstance(length, int):
        text = str(planned_input.get("text") or "")
        length = len(text) if text else 0
    return f"已复制 {length} 个字符到剪贴板。" if length else "已写入剪贴板。"


def _clipboard_read_summary(result: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    text = str(data.get("text") or "")
    text_length = data.get("text_length")
    truncated = bool(data.get("truncated"))
    if not text:
        return "剪贴板是空的。" if text_length == 0 else ""
    suffix = "（内容较长，已截断预览）" if truncated else ""
    return f"剪贴板内容：{text}{suffix}"


def _notes_create_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    title = str(data.get("title") or planned_input.get("title") or "").strip()
    length = data.get("body_length")
    if not isinstance(length, int):
        body = str(planned_input.get("body") or "")
        length = len(body) if body else 0
    detail = f"：{title}" if title else ""
    suffix = f"（{length} 个字符）" if length else ""
    return f"已创建备忘录{detail}{suffix}。"


def _reminders_create_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    title = str(data.get("title") or planned_input.get("title") or "").strip()
    due_at = str(data.get("due_at") or planned_input.get("due_at") or "").strip()
    if not title:
        return ""
    return f"已创建提醒事项：{title}{f'（{due_at}）' if due_at else ''}。"


def _calendar_create_event_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    title = str(data.get("title") or planned_input.get("title") or "").strip()
    start_at = str(data.get("start_at") or planned_input.get("start_at") or "").strip()
    end_at = str(data.get("end_at") or planned_input.get("end_at") or "").strip()
    if not title:
        return ""
    time_text = ""
    if start_at and end_at:
        time_text = f"（{start_at} - {end_at}）"
    elif start_at:
        time_text = f"（{start_at}）"
    return f"已创建日历事件：{title}{time_text}。"


def _desktop_open_path_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    path = _desktop_path_summary_path(result, planned_input)
    if not path:
        return ""
    if data.get("is_dir") is True:
        return f"已打开文件夹：{path}。"
    return f"已打开文件：{path}。"


def _desktop_open_path_with_app_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    path = _desktop_path_summary_path(result, planned_input)
    app_name = str(data.get("app_name") or planned_input.get("app_name") or "").strip()
    if not path:
        return ""
    app_text = f"用 {app_name} " if app_name else "用应用"
    if data.get("is_dir") is True:
        return f"已{app_text}打开文件夹：{path}。"
    return f"已{app_text}打开文件：{path}。"


def _desktop_path_summary_path(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    if data.get("desktop_object"):
        return str(
            data.get("display_path")
            or data.get("resolved_path")
            or data.get("expanded_path")
            or data.get("path")
            or planned_input.get("path")
            or ""
        ).strip()
    return str(data.get("path") or planned_input.get("path") or "").strip()


def _terminal_run_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    command = str(planned_input.get("command") or "").strip()
    command_text = f"：{command}" if command else ""
    stdout = str(result.get("stdout") or "").strip()
    stderr = str(result.get("stderr") or "").strip()
    if result.get("ok"):
        if stdout:
            return f"已运行命令{command_text}。\n输出：{_terminal_output_preview(stdout)}"
        return f"已运行命令{command_text}。"
    parts = [f"命令执行失败{command_text}。"]
    returncode = result.get("returncode")
    if returncode not in (None, ""):
        parts.append(f"退出码：{returncode}。")
    if stderr:
        parts.append(f"stderr：{_terminal_output_preview(stderr)}")
    elif stdout:
        parts.append(f"stdout：{_terminal_output_preview(stdout)}")
    return " ".join(parts)


def _data_analyze_summary(result: dict[str, Any], planned_input: dict[str, Any]) -> str:
    path = str(result.get("path") or planned_input.get("path") or "").strip()
    artifact = result.get("artifact") if isinstance(result.get("artifact"), dict) else {}
    artifact_path = str(
        artifact.get("path")
        or result.get("artifact_path")
        or planned_input.get("artifact_path")
        or ""
    ).strip()
    rows = result.get("rows")
    columns = result.get("columns")
    column_count = len(columns) if isinstance(columns, list) else None
    source = f"「{path}」" if path else "数据文件"
    facts = []
    if rows not in (None, ""):
        facts.append(f"{rows} 行")
    if column_count is not None:
        facts.append(f"{column_count} 列")
    fact_text = f"（{ '、'.join(facts) }）" if facts else ""
    artifact_text = f"报告已写入 {artifact_path}。" if artifact_path else ""
    return f"已分析{source}{fact_text}。{artifact_text}".strip()


def _terminal_output_preview(value: str) -> str:
    text = str(value or "").strip()
    if len(text) > 600:
        return f"{text[:600]}..."
    return text


def _sentence(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if text.endswith(("。", ".", "!", "！", "?", "？")):
        return text
    return f"{text}。"


def _combine_daily_desktop_summaries(summaries: list[str]) -> str:
    sentences = [_sentence(summary) for summary in summaries if str(summary or "").strip()]
    return " ".join(sentences)


def _model_followup_context_payload(
    planned_tool_requests: list[dict[str, Any]],
    selection_payload: dict[str, Any],
    *,
    allowed_tools: list[str],
    timeline: list[dict[str, Any]],
) -> dict[str, Any]:
    content_requests = [
        request
        for request in planned_tool_requests
        if isinstance(request, dict)
        and bool(request.get("continue_to_model"))
    ]
    if not content_requests:
        content_requests = _model_followup_context_requests_from_selection_target(
            planned_tool_requests,
            selection_payload,
        )
    if not content_requests:
        return {}
    context_only_followup = any(
        bool(request.get("_context_only_followup"))
        for request in content_requests
        if isinstance(request, Mapping)
    )
    observation_content_requests = [
        request
        for request in content_requests
        if not _tool_request_requires_model_materialization(request)
    ]
    materialization_content_requests = [
        request
        for request in content_requests
        if _tool_request_requires_model_materialization(request)
    ]
    if materialization_content_requests and not observation_content_requests:
        observation_content_requests = _model_followup_pre_materialization_requests(
            planned_tool_requests,
            materialization_content_requests,
        )
    allowed = {
        str(tool or "").strip()
        for tool in allowed_tools
        if str(tool or "").strip()
    }
    artifacts_expected = _string_list(selection_payload.get("artifacts_expected"))
    planning_reason_requests = [
        request
        for request in content_requests
        if str(request.get("replan_recovery_identity") or "").strip()
    ] or content_requests
    planning_reasons = _ordered_text_list(
        [
            str(request.get("planning_reason") or "").strip()
            for request in planning_reason_requests
            if str(request.get("planning_reason") or "").strip()
        ]
    )
    planning_reason = (
        planning_reasons[0]
        if len(planning_reasons) == 1
        else "planner_model_followup_context"
    )
    observation_tools = _ordered_text_list(
        [
            str(request.get("tool") or "").strip()
            for request in observation_content_requests
            if str(request.get("tool") or "").strip()
        ]
    )
    payload: dict[str, Any] = {
        "source": "runtime_planner",
        "status": "ready",
        "planning_reason": planning_reason,
        "observation_tools": observation_tools,
        "artifact_write_allowed": "artifact.write" in allowed,
    }
    followup_target = _model_followup_target_payload(selection_payload, allowed)
    if followup_target:
        payload["followup_target"] = followup_target
    if artifacts_expected:
        payload["artifacts_expected"] = artifacts_expected
    materialization_requests_for_pending = (
        []
        if followup_target
        and _materialization_requests_are_artifact_writes(
            materialization_content_requests
        )
        else materialization_content_requests
    )
    pending_plan_steps = (
        []
        if context_only_followup
        else _model_followup_pending_plan_steps(
            selection_payload,
            observation_content_requests,
        )
    )
    if pending_plan_steps:
        payload["pending_plan_steps"] = pending_plan_steps
    pending_execution_requests = (
        []
        if context_only_followup
        else _model_followup_pending_execution_requests(
            selection_payload,
            observation_content_requests,
            allowed,
        )
    )
    materialization_execution_requests = (
        []
        if context_only_followup
        else _model_followup_materialization_execution_requests(
            selection_payload,
            materialization_requests_for_pending,
            allowed,
        )
    )
    if materialization_execution_requests:
        pending_execution_requests = _merged_pending_execution_requests(
            pending_execution_requests,
            materialization_execution_requests,
        )
    deferred_execution_requests = (
        []
        if context_only_followup
        else _model_followup_deferred_execution_requests(
            content_requests,
            allowed,
        )
    )
    if deferred_execution_requests:
        pending_execution_requests = _merged_pending_execution_requests(
            pending_execution_requests,
            deferred_execution_requests,
        )
    if pending_execution_requests:
        payload["pending_execution_requests"] = pending_execution_requests
    task_core_payload = _model_followup_task_core_payload(selection_payload)
    if task_core_payload:
        payload["task_core"] = task_core_payload
    content_snapshots = followup_content_snapshots(timeline, observation_tools)
    content_snapshot = content_snapshots[-1] if content_snapshots else latest_followup_content_snapshot(timeline, observation_tools)
    if content_snapshot:
        payload["content_snapshot"] = content_snapshot
    if content_snapshots:
        payload["content_snapshots"] = content_snapshots
    for key in ("decision_id", "plan_id", "intent_kind"):
        value = str(selection_payload.get(key) or "").strip()
        if value:
            payload[key] = value
    return payload


def _model_followup_pre_materialization_requests(
    planned_tool_requests: list[dict[str, Any]],
    materialization_requests: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    materialization_ids = {id(request) for request in materialization_requests}
    observed: list[dict[str, Any]] = []
    for request in planned_tool_requests:
        if not isinstance(request, dict):
            continue
        if id(request) in materialization_ids:
            break
        if str(request.get("tool") or "").strip() and not (
            _tool_request_requires_model_materialization(request)
        ):
            observed.append(request)
    preferred = [
        request
        for request in observed
        if str(request.get("tool") or "").strip()
        in _MODEL_FOLLOWUP_PRIMARY_OBSERVATION_TOOLS
    ]
    return preferred[-1:] if preferred else observed


def _materialization_requests_are_artifact_writes(
    requests: Iterable[Mapping[str, Any]],
) -> bool:
    tools = [
        str(request.get("tool") or request.get("tool_name") or "").strip()
        for request in requests
        if isinstance(request, Mapping)
    ]
    return bool(tools) and set(tools) == {"artifact.write"}


_MODEL_FOLLOWUP_PRIMARY_OBSERVATION_TOOLS = frozenset(
    {
        "browser.extract_text",
        "browser.open_url_and_extract_text",
        "clipboard.read",
        "data.analyze",
        "desktop.inspect_app",
        "desktop.read_ui",
        "desktop.ui_elements",
        "file.read",
        "file.search",
        "screen.capture",
        "terminal.run",
        "workspace.list",
        "workspace.read",
    }
)


def _model_followup_context_requests_from_selection_target(
    planned_tool_requests: list[dict[str, Any]],
    selection_payload: Mapping[str, Any],
) -> list[dict[str, Any]]:
    if not _selection_payload_has_model_followup_target(selection_payload):
        return []
    target = (
        selection_payload.get("followup_target")
        if isinstance(selection_payload.get("followup_target"), Mapping)
        else {}
    )
    post_action_observation = (
        target.get("post_action_observation")
        if isinstance(target.get("post_action_observation"), Mapping)
        else {}
    )
    preferred_tools = _ordered_text_list(
        [
            str(post_action_observation.get("tool") or "").strip(),
            "desktop.ui_elements",
            "desktop.read_ui",
            "screen.capture",
        ]
    )
    for request in reversed(planned_tool_requests):
        if not isinstance(request, dict):
            continue
        tool_name = str(request.get("tool") or "").strip()
        if preferred_tools and tool_name not in preferred_tools:
            continue
        return [{**request, "continue_to_model": True, "_context_only_followup": True}]
    return []


def _model_followup_task_core_payload(selection_payload: Mapping[str, Any]) -> dict[str, Any]:
    for key in ("task_core", "yachiyo_task_core"):
        value = selection_payload.get(key)
        if isinstance(value, Mapping) and value:
            return dict(value)
    runtime_plan = (
        selection_payload.get("runtime_plan")
        if isinstance(selection_payload.get("runtime_plan"), Mapping)
        else {}
    )
    value = runtime_plan.get("task_core") if isinstance(runtime_plan, Mapping) else {}
    return dict(value) if isinstance(value, Mapping) and value else {}


def _model_followup_pending_plan_steps(
    selection_payload: Mapping[str, Any],
    content_requests: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    steps = _selection_tool_plan_steps(selection_payload)
    observation_tools = [
        str(request.get("tool") or "").strip()
        for request in content_requests
        if str(request.get("tool") or "").strip()
    ]
    if not steps or not observation_tools:
        return []

    start_index = _pending_plan_step_start_index(steps, observation_tools)
    if start_index <= 0:
        return []

    pending_steps: list[dict[str, Any]] = []
    task_core = _model_followup_task_core_payload(selection_payload)
    for step in steps[start_index:]:
        step_payload = _model_followup_plan_step_payload(step)
        if not step_payload:
            continue
        step_payload.update(
            _model_followup_task_core_step_runtime_trace(
                task_core,
                str(step_payload.get("step_id") or ""),
            )
        )
        pending_steps.append(step_payload)
        if len(pending_steps) >= 5:
            break
    return pending_steps


def _model_followup_pending_execution_requests(
    selection_payload: Mapping[str, Any],
    content_requests: list[dict[str, Any]],
    allowed: set[str],
) -> list[dict[str, Any]]:
    requests = _selection_execution_envelope_requests(selection_payload)
    observation_tools = [
        str(request.get("tool") or "").strip()
        for request in content_requests
        if str(request.get("tool") or "").strip()
    ]
    if not requests or not observation_tools:
        return []

    start_index = _pending_execution_request_start_index(requests, observation_tools)
    if start_index <= 0:
        return []

    pending_requests: list[dict[str, Any]] = []
    for request in requests[start_index:]:
        request_payload = _model_followup_execution_request_payload(request, allowed)
        if not request_payload:
            continue
        pending_requests.append(request_payload)
        if len(pending_requests) >= 5:
            break
    return pending_requests


def _model_followup_materialization_execution_requests(
    selection_payload: Mapping[str, Any],
    content_requests: Iterable[Mapping[str, Any]],
    allowed: set[str],
) -> list[dict[str, Any]]:
    materialization_requests = [
        request
        for request in content_requests
        if isinstance(request, Mapping)
        and _tool_request_requires_model_materialization(request)
    ]
    if not materialization_requests:
        return []
    envelope_requests = _selection_execution_envelope_requests(selection_payload)
    start_indexes = [
        index
        for request in materialization_requests
        for index in [
            _matching_execution_envelope_request_index(envelope_requests, request)
        ]
        if index >= 0
    ]
    raw_pending_requests: Iterable[Mapping[str, Any]]
    if start_indexes:
        raw_pending_requests = envelope_requests[min(start_indexes) :]
    else:
        raw_pending_requests = materialization_requests

    pending: list[dict[str, Any]] = []
    for request in raw_pending_requests:
        if not isinstance(request, Mapping):
            continue
        request_payload = _model_followup_execution_request_payload(request, allowed)
        if request_payload:
            pending.append(request_payload)
    return pending


def _matching_execution_envelope_request_index(
    envelope_requests: list[Mapping[str, Any]],
    request: Mapping[str, Any],
) -> int:
    if not envelope_requests:
        return -1
    request_id = str(request.get("request_id") or "").strip()
    step_id = str(request.get("step_id") or request.get("planner_step_id") or "").strip()
    for index, candidate in enumerate(envelope_requests):
        candidate_request_id = str(candidate.get("request_id") or "").strip()
        if request_id and candidate_request_id == request_id:
            return index
        candidate_step_id = str(candidate.get("step_id") or "").strip()
        if step_id and candidate_step_id == step_id:
            return index
    request_tool = str(request.get("tool") or request.get("tool_name") or "").strip()
    request_input = (
        request.get("input")
        if isinstance(request.get("input"), Mapping)
        else request.get("input_preview")
        if isinstance(request.get("input_preview"), Mapping)
        else {}
    )
    for index, candidate in enumerate(envelope_requests):
        candidate_tool = str(
            candidate.get("tool_name") or candidate.get("tool") or ""
        ).strip()
        if candidate_tool != request_tool:
            continue
        candidate_input = (
            candidate.get("input") if isinstance(candidate.get("input"), Mapping) else {}
        )
        if _model_materialization_inputs_match(candidate_input, request_input):
            return index
    return -1


def _model_materialization_inputs_match(
    candidate_input: Mapping[str, Any],
    request_input: Mapping[str, Any],
) -> bool:
    for key in (
        "app_name",
        "path",
        "target_path",
        "body_source",
        "selection_source",
        "app_selection_source",
        "action",
    ):
        request_value = request_input.get(key)
        if request_value in (None, "", [], {}):
            continue
        if candidate_input.get(key) != request_value:
            return False
    return True


def _model_followup_deferred_execution_requests(
    content_requests: list[dict[str, Any]],
    allowed: set[str],
) -> list[dict[str, Any]]:
    pending: list[dict[str, Any]] = []
    for index, request in enumerate(content_requests, start=1):
        if not isinstance(request, Mapping):
            continue
        tool_name = str(request.get("deferred_tool") or "").strip()
        if not tool_name or (allowed and tool_name not in allowed):
            continue
        raw_input = (
            dict(request.get("deferred_input"))
            if isinstance(request.get("deferred_input"), Mapping)
            else {}
        )
        if not raw_input:
            continue
        pending.append(
            {
                "request_id": _deferred_execution_request_id(
                    request,
                    tool_name=tool_name,
                    index=index,
                ),
                "tool_name": tool_name,
                "capability_id": "desktop.ui_operation",
                "input_preview": raw_input,
                "planning_reason": str(
                    request.get("planning_reason") or "planner_followup_deferred_ui_action"
                ).strip(),
                "status": "planned",
                "runtime_doctrine": str(
                    request.get("runtime_doctrine") or "discover_operate_verify"
                ).strip(),
                "runtime_stage": "operate",
                "runtime_role": _deferred_ui_runtime_role(tool_name),
                "approval_required": _deferred_ui_tool_requires_approval(tool_name),
                "requires_post_action_verification": True,
                "source": str(request.get("source") or "runtime_planner").strip(),
            }
        )
    return pending


def _auto_deferred_observed_ui_followup_requests(
    planned_tool_requests: Iterable[Mapping[str, Any]],
    allowed_tools: Iterable[str],
    timeline: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    allowed = {str(tool or "").strip() for tool in allowed_tools if str(tool or "").strip()}
    if not allowed:
        return []
    for index, request in enumerate(planned_tool_requests, start=1):
        if not isinstance(request, Mapping) or not bool(request.get("continue_to_model")):
            continue
        target = _deferred_observed_ui_target_from_request(request)
        if not target:
            continue
        target = _deferred_observed_ui_target_with_timeline_context(
            target,
            request,
            timeline,
        )
        if not _runtime_planner_deferred_observation_scope_matches(
            request,
            target,
            timeline,
        ):
            continue
        tool_name = str(request.get("deferred_tool") or "").strip()
        scoped_allowed = _deferred_observed_ui_scoped_allowed_tools(
            tool_name,
            target,
            allowed,
        )
        if not scoped_allowed:
            continue
        target_label = str(target.get("target") or "").strip()
        role_filter = str(target.get("role_filter") or "").strip()
        if not _latest_desktop_observation_has_target_match(
            timeline,
            target_label,
            role_filter,
        ):
            retry_request = _deferred_observed_ui_observation_retry_request(
                request,
                target,
                allowed,
                timeline,
            )
            if retry_request:
                return [retry_request]
            continue
        observation_source = _latest_desktop_observation_tool(timeline)
        if observation_source:
            target["observation_source"] = observation_source
        requests = _auto_desktop_observed_action_followup_requests(
            {"followup_target": target},
            scoped_allowed,
            timeline,
            planning_reason=_deferred_observed_ui_planning_reason(request),
        )
        if requests:
            annotated = _annotate_deferred_observed_ui_followup_requests(
                requests,
                request,
                tool_name=tool_name,
                index=index,
            )
            continuation = _deferred_observed_ui_continuation_requests(request, allowed)
            if not continuation:
                continuation = _deferred_media_playback_continuation_requests(
                    request,
                    target,
                    allowed,
                    planning_reason=_deferred_observed_ui_planning_reason(request),
                )
            return [*annotated, *continuation]
    return []


def _auto_deferred_observed_ui_can_complete_without_model(
    planned_tool_requests: Iterable[Mapping[str, Any]],
    allowed_tools: Iterable[str],
    timeline: list[dict[str, Any]],
    *,
    tool_timeline_start: int,
) -> bool:
    requests = _auto_deferred_observed_ui_followup_requests(
        planned_tool_requests,
        allowed_tools,
        timeline,
    )
    requests = _drop_completed_auto_followup_prefix(
        requests,
        timeline,
        tool_timeline_start=tool_timeline_start,
    )
    return bool(requests) and not _replan_recovery_requests_need_model_followup(requests)


def _deferred_observed_ui_planning_reason(request: Mapping[str, Any]) -> str:
    if _string_list(request.get("replan_triggers")) or _string_list(
        request.get("replan_signal_ids")
    ):
        return "planner_replan_app_search_observed_result"
    return str(
        request.get("planning_reason") or "planner_followup_deferred_ui_action"
    ).strip() or "planner_followup_deferred_ui_action"


def _deferred_observed_ui_scoped_allowed_tools(
    tool_name: str,
    target: Mapping[str, Any],
    allowed: set[str],
) -> list[str]:
    clean_tool = str(tool_name or "").strip()
    if not clean_tool:
        return []
    observation_tools = (
        "desktop.read_ui",
        "desktop.ui_elements",
        "desktop.active_window",
    )
    app_name = _observed_action_app_name(target)
    tools: list[str] = []
    if clean_tool in {
        "app.open_and_click_ui_element",
        "app.focus_and_click_ui_element",
        "desktop.click_ui_element",
        "desktop.safe_click",
        "desktop.click",
    }:
        if clean_tool in allowed:
            tools.append(clean_tool)
        if app_name:
            tools.extend(
                tool
                for tool in (
                    "app.focus_and_click_ui_element",
                    "app.open_and_click_ui_element",
                )
                if tool in allowed
            )
        tools.extend(
            tool
            for tool in (
                "desktop.click_ui_element",
                "desktop.safe_click",
                "desktop.click",
            )
            if tool in allowed
        )
    elif clean_tool in {
        "app.open_and_type_into_ui_element",
        "app.focus_and_type_into_ui_element",
        "desktop.type_into_ui_element",
        "desktop.safe_type_text",
        "desktop.type_text",
        "desktop.type",
    }:
        if clean_tool in allowed:
            tools.append(clean_tool)
        if app_name:
            tools.extend(
                tool
                for tool in (
                    "app.focus_and_type_into_ui_element",
                    "app.open_and_type_into_ui_element",
                    "app.focus_and_click_ui_element",
                    "app.open_and_click_ui_element",
                )
                if tool in allowed
            )
        tools.extend(
            tool
            for tool in (
                "desktop.type_into_ui_element",
                "desktop.click_ui_element",
                "desktop.safe_click",
                "desktop.click",
                "desktop.safe_type_text",
                "desktop.type_text",
                "desktop.type",
            )
            if tool in allowed
        )
    else:
        return []
    tools.extend(tool for tool in observation_tools if tool in allowed)
    return _ordered_text_list(tools)


def _deferred_observed_ui_continuation_requests(
    request: Mapping[str, Any],
    allowed: set[str],
) -> list[dict[str, Any]]:
    raw_continuation = request.get("deferred_continuation")
    if not isinstance(raw_continuation, list):
        return []
    continuation: list[dict[str, Any]] = []
    for item in raw_continuation:
        if not isinstance(item, Mapping):
            continue
        next_request = dict(item)
        tool_name = str(next_request.get("tool") or "").strip()
        if not tool_name or (allowed and tool_name not in allowed):
            continue
        continuation.append(next_request)
    return continuation


def _deferred_media_playback_continuation_requests(
    request: Mapping[str, Any],
    target: Mapping[str, Any],
    allowed: set[str],
    *,
    planning_reason: str,
) -> list[dict[str, Any]]:
    if str(request.get("intent_kind") or "").strip() != "media_playback":
        return []
    if str(target.get("target_action") or "").strip() != "type_text":
        return []
    app_name = _observed_action_app_name(target)
    if not app_name:
        return []
    source = str(request.get("source") or "runtime_planner").strip() or "runtime_planner"
    submit_request = _media_search_submit_request(
        allowed,
        source=source,
        planning_reason=planning_reason,
    )
    if not submit_request:
        return []
    result_selection = {
        "target": "first result",
        "role_filter": "",
        "limit": 80,
        "click_count": 1,
    }
    result_observation = _discovered_media_result_observation_request(
        app_name,
        {"result_selection": result_selection},
        allowed,
        source=source,
        planning_reason=planning_reason,
    )
    if not result_observation:
        return [submit_request]
    return [submit_request, result_observation]


def _deferred_observed_ui_observation_retry_request(
    request: Mapping[str, Any],
    target: Mapping[str, Any],
    allowed: set[str],
    timeline: list[dict[str, Any]],
) -> dict[str, Any]:
    if "desktop.read_ui" not in allowed:
        return {}
    if str(request.get("tool") or "").strip() == "desktop.read_ui":
        return {}
    latest_observation = _latest_desktop_observation_event(timeline)
    if str(latest_observation.get("tool") or "").strip() != "desktop.ui_elements":
        return {}
    payload = {
        key: value
        for key, value in {
            "app_name": target.get("app_name"),
            "role_filter": target.get("role_filter"),
            "limit": target.get("limit"),
        }.items()
        if value not in (None, "", [], {})
    }
    if "limit" not in payload:
        payload["limit"] = 80
    retry = _request_like(
        "desktop.read_ui",
        payload,
        source=str(request.get("source") or "runtime_planner").strip(),
        planning_reason=str(
            request.get("planning_reason") or "planner_retry_deferred_ui_observation"
        ).strip()
        or "planner_retry_deferred_ui_observation",
    )
    retry["continue_to_model"] = True
    retry["deferred_tool"] = str(request.get("deferred_tool") or "").strip()
    raw_input = request.get("deferred_input")
    if isinstance(raw_input, Mapping):
        retry["deferred_input"] = dict(raw_input)
    raw_context = request.get("deferred_context")
    if isinstance(raw_context, Mapping):
        retry["deferred_context"] = dict(raw_context)
    raw_verifier_context = request.get("deferred_verifier_context")
    if isinstance(raw_verifier_context, Mapping):
        retry["deferred_verifier_context"] = dict(raw_verifier_context)
    raw_continuation = request.get("deferred_continuation")
    if isinstance(raw_continuation, list):
        retry["deferred_continuation"] = [
            dict(item) for item in raw_continuation if isinstance(item, Mapping)
        ]
    for key, value in _request_observability_metadata(request).items():
        retry.setdefault(key, value)
    # This request only re-observes state after an already-approved action.
    # Never inherit the action's approval/risk/stage contract onto the verifier.
    retry.update(
        {
            "approval_required": False,
            "risk_level": "low",
            "requires_observation": True,
            "requires_post_action_verification": False,
            "runtime_stage": "verify",
            "runtime_role": "verify_result",
        }
    )
    request_id = str(request.get("request_id") or "").strip()
    if request_id:
        retry["request_id"] = f"{request_id}:retry:desktop.read_ui"
    retry["observation_retry"] = {
        "from_tool": "desktop.ui_elements",
        "reason": "target_not_found",
        "target": str(target.get("target") or "").strip(),
    }
    return retry


def _deferred_observed_ui_target_from_request(
    request: Mapping[str, Any],
) -> dict[str, Any]:
    tool_name = str(request.get("deferred_tool") or "").strip()
    raw_input = (
        request.get("deferred_input")
        if isinstance(request.get("deferred_input"), Mapping)
        else {}
    )
    if not tool_name or not raw_input:
        return {}
    click_tools = {
        "app.open_and_click_ui_element",
        "app.focus_and_click_ui_element",
        "desktop.click_ui_element",
        "desktop.safe_click",
        "desktop.click",
    }
    type_tools = {
        "app.open_and_type_into_ui_element",
        "app.focus_and_type_into_ui_element",
        "desktop.type_into_ui_element",
        "desktop.safe_type_text",
        "desktop.type_text",
        "desktop.type",
    }
    if tool_name in click_tools:
        target_action = "click"
    elif tool_name in type_tools:
        target_action = "type_text"
    else:
        return {}
    target_label = str(raw_input.get("target") or "").strip()
    if not target_label:
        return {}
    target: dict[str, Any] = {
        "kind": "desktop_observed_action",
        "target_action": target_action,
        "target": target_label,
        "role_filter": str(raw_input.get("role_filter") or "").strip(),
        "limit": _clean_model_followup_int(raw_input.get("limit"), default=80),
    }
    app_name = str(raw_input.get("app_name") or request.get("target_app_name") or "").strip()
    if app_name:
        target["app_name"] = app_name
    app_query = str(
        raw_input.get("app_query")
        or request.get("target_app_query")
        or request.get("app_query")
        or ""
    ).strip()
    if app_query:
        target["app_query"] = app_query
    if target_action == "click":
        target["click_count"] = _clean_model_followup_int(
            raw_input.get("click_count"),
            default=1,
        )
    else:
        text = str(raw_input.get("text") or "")
        if not text:
            return {}
        target["text"] = text
        submit_action = str(raw_input.get("submit_action") or "").strip()
        if submit_action:
            target["submit_action"] = submit_action
    return {key: value for key, value in target.items() if value not in ("", None, [], {})}


def _deferred_observed_ui_target_with_timeline_context(
    target: Mapping[str, Any],
    request: Mapping[str, Any],
    timeline: list[dict[str, Any]],
) -> dict[str, Any]:
    resolved = dict(target)
    deferred_input = (
        request.get("deferred_input")
        if isinstance(request.get("deferred_input"), Mapping)
        else {}
    )
    app_query = str(
        resolved.get("app_query")
        or resolved.get("target_app_query")
        or deferred_input.get("query")
        or deferred_input.get("app_query")
        or request.get("target_app_query")
        or ""
    ).strip()
    if app_query:
        resolved["app_query"] = app_query
        resolved["target_app_query"] = app_query
    app_name = str(resolved.get("app_name") or resolved.get("target_app_name") or "").strip()
    if app_name and not _runtime_planner_placeholder_app_name(app_name):
        return resolved
    discovered = _discovered_app_name_for_query(timeline, app_query) if app_query else ""
    if not discovered:
        discovered = _latest_replan_context_app_name(timeline, request_id="")
    if discovered and not _runtime_planner_placeholder_app_name(discovered):
        resolved["app_name"] = discovered
        resolved["target_app_name"] = discovered
    return resolved


def _annotate_deferred_observed_ui_followup_requests(
    requests: list[dict[str, Any]],
    source_request: Mapping[str, Any],
    *,
    tool_name: str,
    index: int,
) -> list[dict[str, Any]]:
    deferred_context = (
        source_request.get("deferred_context")
        if isinstance(source_request.get("deferred_context"), Mapping)
        else {}
    )
    request_id = (
        _runtime_planner_deferred_root_request_id(
            source_request,
            deferred_context,
            tool_name=tool_name,
        )
        or _deferred_execution_request_id(
            source_request,
            tool_name=tool_name,
            index=index,
        )
    )
    deferred_verifier_context = (
        source_request.get("deferred_verifier_context")
        if isinstance(source_request.get("deferred_verifier_context"), Mapping)
        else {}
    )
    annotated: list[dict[str, Any]] = []
    for request_index, request in enumerate(requests):
        item = dict(request)
        is_verification_request = _replan_observed_action_verification_request(
            item
        )
        if request_id:
            item["request_id"] = (
                request_id if request_index == 0 else f"{request_id}:verify:{request_index}"
            )
        for key in (
            "decision_id",
            "plan_id",
            "tool_plan_id",
            "intent_kind",
            "core_id",
            "workspace_id",
            "task_id",
            "run_id",
            "runtime_doctrine",
            "requires_post_action_verification",
            "replan_signal_ids",
            "replan_triggers",
        ):
            value = source_request.get(key)
            if value in (None, "", [], {}) or key in item:
                continue
            item[key] = value
        for key in (
            "step_id",
            "planner_step_id",
            "capability_id",
            "task_todo",
            "task_checkpoints",
            "task_workspace_items",
            "approval_required",
            "approval_status",
            "risk_level",
            "depends_on",
            "runtime_stage",
            "runtime_role",
            "requires_post_action_verification",
            "action_target",
            "verification_targets",
        ):
            value = deferred_context.get(key)
            if value in (None, "", [], {}) or key in item:
                continue
            item[key] = value
        if item.get("step_id") and not item.get("planner_step_id"):
            item["planner_step_id"] = str(item.get("step_id") or "").strip()
        if is_verification_request and deferred_verifier_context:
            for key in (
                "step_id",
                "planner_step_id",
                "capability_id",
                "depends_on",
                "task_todo",
                "task_checkpoints",
                "task_workspace_items",
                "verification_targets",
                "task_verification_targets",
                "verification_predicate_kind",
            ):
                value = deferred_verifier_context.get(key)
                if value not in (None, "", [], {}):
                    item[key] = value
            if item.get("step_id"):
                # The generated verifier initially inherits the deferred
                # action's planner_step_id.  Replace it with the dedicated
                # verifier identity; otherwise task progress opens a false
                # replan even though GoalContract correlation succeeds.
                item["planner_step_id"] = str(
                    deferred_verifier_context.get("planner_step_id")
                    or item.get("step_id")
                    or ""
                ).strip()
            verifier_action_target = deferred_verifier_context.get("action_target")
            if isinstance(verifier_action_target, Mapping):
                item["action_target"] = dict(verifier_action_target)
            item["source"] = str(
                deferred_verifier_context.get("source") or "runtime_verification"
            ).strip()
            verifier_reason = str(
                deferred_verifier_context.get("planning_reason") or ""
            ).strip()
            if verifier_reason:
                item["planning_reason"] = verifier_reason
            item["approval_required"] = False
            item["risk_level"] = "low"
            item["runtime_stage"] = "verify"
            item["runtime_role"] = "verify_result"
        else:
            action_target = deferred_context.get("action_target")
            if request_index == 0 and isinstance(action_target, Mapping):
                # The follow-up helper uses an internal observed-action target
                # while the immutable GoalContract is bound to the planner's
                # canonical action target.  Preserve that exact target across
                # the observation -> action transformation so verifier
                # evidence remains contract-correlated.
                item["action_target"] = dict(action_target)
            item.setdefault("runtime_stage", "operate" if request_index == 0 else "verify")
            item.setdefault("runtime_role", _deferred_ui_runtime_role(tool_name))
        if is_verification_request:
            verifier_tool = str(item.get("tool") or "").strip()
            if verifier_tool not in READ_ONLY_OBSERVATION_TOOLS:
                return []
            action_step_id = str(
                deferred_context.get("step_id")
                or deferred_context.get("planner_step_id")
                or ""
            ).strip()
            if not action_step_id:
                return []
            item["approval_required"] = False
            item["risk_level"] = "low"
            item["runtime_stage"] = "verify"
            item["runtime_role"] = "verify_result"
            item["requires_observation"] = True
            item["requires_post_action_verification"] = False
            item["depends_on"] = [action_step_id]
            item["verification_target_step_ids"] = [action_step_id]
            if request_id:
                item["source_request_id"] = request_id
        annotated.append(item)
    return annotated


def _runtime_planner_deferred_root_request_id(
    source_request: Mapping[str, Any],
    deferred_context: Mapping[str, Any],
    *,
    tool_name: str,
) -> str:
    scope = (
        source_request.get("runtime_observation_scope")
        if isinstance(source_request.get("runtime_observation_scope"), Mapping)
        else {}
    )
    if not scope or str(source_request.get("deferred_tool") or "").strip() != str(
        tool_name or ""
    ).strip():
        return ""
    plan_id = str(deferred_context.get("plan_id") or "").strip()
    step_id = str(
        deferred_context.get("step_id")
        or deferred_context.get("planner_step_id")
        or ""
    ).strip()
    request_id = str(deferred_context.get("request_id") or "").strip()
    if (
        not plan_id
        or not step_id
        or str(scope.get("plan_id") or "").strip() != plan_id
        or not request_id.startswith(f"{plan_id}:request:")
    ):
        return ""
    return request_id


def _deferred_execution_request_id(
    request: Mapping[str, Any],
    *,
    tool_name: str,
    index: int,
) -> str:
    request_id = str(request.get("request_id") or "").strip()
    if request_id:
        return f"{request_id}:deferred:{tool_name}"
    plan_id = str(request.get("plan_id") or "").strip()
    if plan_id:
        return f"{plan_id}:deferred:{index}:{tool_name}"
    return f"deferred:{index}:{tool_name}"


def _deferred_ui_runtime_role(tool_name: str) -> str:
    clean_tool = str(tool_name or "").strip()
    if clean_tool.endswith("_type_into_ui_element") or clean_tool in {
        "desktop.type_into_ui_element",
        "desktop.safe_type_text",
        "desktop.type_text",
        "desktop.type",
    }:
        return "type_ui"
    if clean_tool.endswith("_click_ui_element") or clean_tool in {
        "desktop.click_ui_element",
        "desktop.safe_click",
        "desktop.click",
    }:
        return "click_ui"
    return "operate_ui"


def _deferred_ui_tool_requires_approval(tool_name: str) -> bool:
    clean_tool = str(tool_name or "").strip()
    return clean_tool in {
        "app.open_and_click_ui_element",
        "app.focus_and_click_ui_element",
        "app.open_and_type_into_ui_element",
        "app.focus_and_type_into_ui_element",
        "desktop.click_ui_element",
        "desktop.type_into_ui_element",
        "desktop.safe_click",
        "desktop.click",
        "desktop.safe_type_text",
        "desktop.type_text",
        "desktop.type",
    }


def _merged_pending_execution_requests(
    first: list[dict[str, Any]],
    second: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    merged: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for request in [*first, *second]:
        tool_name = str(request.get("tool_name") or request.get("tool") or "").strip()
        input_preview = (
            request.get("input_preview")
            if isinstance(request.get("input_preview"), Mapping)
            else request.get("input")
            if isinstance(request.get("input"), Mapping)
            else {}
        )
        key = (tool_name, repr(sorted(dict(input_preview).items())))
        if key in seen:
            continue
        seen.add(key)
        merged.append(request)
    return merged


def _selection_execution_envelope_requests(
    selection_payload: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    for key in (
        "yachiyo_execution_envelope",
        "execution_envelope",
        "runtime_execution_envelope",
    ):
        envelope = selection_payload.get(key)
        if not isinstance(envelope, Mapping):
            continue
        requests = envelope.get("requests")
        if not isinstance(requests, list):
            continue
        return [request for request in requests if isinstance(request, Mapping)]
    return []


def _pending_execution_request_start_index(
    requests: list[Mapping[str, Any]],
    observation_tools: list[str],
) -> int:
    cursor = 0
    last_match = -1
    for observed_tool in observation_tools:
        for index in range(cursor, len(requests)):
            tool_name = str(
                requests[index].get("tool_name")
                or requests[index].get("tool")
                or ""
            ).strip()
            if tool_name != observed_tool:
                continue
            last_match = index
            cursor = index + 1
            break
    return last_match + 1 if last_match >= 0 else 0


def _model_followup_execution_request_payload(
    request: Mapping[str, Any],
    allowed: set[str],
) -> dict[str, Any]:
    status = str(request.get("status") or "planned").strip()
    tool_name = str(request.get("tool_name") or request.get("tool") or "").strip()
    request_input = (
        dict(request.get("input"))
        if isinstance(request.get("input"), Mapping)
        else {}
    )
    materialization_blocker = bool(
        status in {"blocked", "waiting_approval"}
        and _tool_request_requires_model_materialization(
            {
                "tool": tool_name,
                "input": request_input,
                "continue_to_model": True,
            }
        )
    )
    if status not in {"", "planned"} and not materialization_blocker:
        return {}
    if not tool_name or (allowed and tool_name not in allowed):
        return {}
    payload: dict[str, Any] = {
        "request_id": str(request.get("request_id") or "").strip(),
        "step_id": str(request.get("step_id") or "").strip(),
        "tool_name": tool_name,
        "capability_id": str(request.get("capability_id") or "").strip(),
        "input_preview": request_input,
        "planning_reason": str(request.get("planning_reason") or "").strip(),
        "status": status or "planned",
    }
    for key in (
        "runtime_doctrine",
        "runtime_stage",
        "runtime_role",
        "source",
        *_RUNTIME_ORCHESTRATION_SCOPE_KEYS,
    ):
        value = str(request.get(key) or "").strip()
        if value:
            payload[key] = value
    for key in (
        "approval_required",
        "continue_to_model",
        "requires_observation",
        "requires_post_action_verification",
    ):
        if bool(request.get(key)):
            payload[key] = True
    for key in (
        "depends_on",
        "fallback_tools",
        "replan_triggers",
        "replan_signal_ids",
    ):
        values = _string_list(request.get(key))
        if values:
            payload[key] = values
    raw_input_bindings = request.get("input_bindings")
    input_bindings = (
        [
            dict(binding)
            for binding in raw_input_bindings
            if isinstance(binding, Mapping)
        ]
        if isinstance(raw_input_bindings, list)
        else []
    )
    if input_bindings:
        payload["input_bindings"] = input_bindings
    action_target = request.get("action_target")
    if isinstance(action_target, Mapping) and action_target:
        payload["action_target"] = dict(action_target)
    task_todo = request.get("task_todo")
    if isinstance(task_todo, Mapping) and task_todo:
        payload["task_todo"] = dict(task_todo)
    for key in (
        "task_checkpoints",
        "task_workspace_items",
        "task_verification_targets",
    ):
        items = [
            dict(item)
            for item in request.get(key, [])
            if isinstance(item, Mapping)
        ]
        if items:
            payload[key] = items
    return {key: value for key, value in payload.items() if value not in ("", [], {})}


def _selection_tool_plan_steps(selection_payload: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    tool_plan = (
        selection_payload.get("tool_plan")
        if isinstance(selection_payload.get("tool_plan"), Mapping)
        else {}
    )
    steps = tool_plan.get("steps") if isinstance(tool_plan, Mapping) else []
    if not isinstance(steps, list):
        return []
    return [step for step in steps if isinstance(step, Mapping)]


def _pending_plan_step_start_index(
    steps: list[Mapping[str, Any]],
    observation_tools: list[str],
) -> int:
    cursor = 0
    last_match = -1
    for observed_tool in observation_tools:
        for index in range(cursor, len(steps)):
            tool_name = str(steps[index].get("tool_name") or "").strip()
            if tool_name != observed_tool:
                continue
            last_match = index
            cursor = index + 1
            break
    return last_match + 1 if last_match >= 0 else 0


def _model_followup_plan_step_payload(step: Mapping[str, Any]) -> dict[str, Any]:
    if str(step.get("status") or "planned").strip() not in {"", "planned"}:
        return {}
    step_id = str(step.get("step_id") or "").strip()
    tool_name = str(step.get("tool_name") or "").strip()
    if not step_id and not tool_name:
        return {}
    payload: dict[str, Any] = {
        "step_id": step_id,
        "title": str(step.get("title") or "").strip(),
        "tool_name": tool_name,
        "capability_id": str(step.get("capability_id") or "").strip(),
        "action": str(step.get("action") or "").strip(),
        "input_preview": (
            dict(step.get("input_preview"))
            if isinstance(step.get("input_preview"), Mapping)
            else {}
        ),
    }
    risk_level = str(step.get("risk_level") or "").strip()
    if risk_level:
        payload["risk_level"] = risk_level
    if bool(step.get("approval_required")):
        payload["approval_required"] = True
    depends_on = _string_list(step.get("depends_on"))
    if depends_on:
        payload["depends_on"] = depends_on
    raw_input_bindings = step.get("input_bindings")
    input_bindings = (
        [
            dict(binding)
            for binding in raw_input_bindings
            if isinstance(binding, Mapping)
        ]
        if isinstance(raw_input_bindings, list)
        else []
    )
    if input_bindings:
        payload["input_bindings"] = input_bindings
    action_target = step.get("action_target")
    if isinstance(action_target, Mapping) and action_target:
        payload["action_target"] = dict(action_target)
    for key in (
        "runtime_doctrine",
        "runtime_stage",
        "runtime_role",
        "requires_observation",
        "requires_post_action_verification",
    ):
        value = step.get(key)
        if value not in (None, "", [], {}):
            payload[key] = value
    return {key: value for key, value in payload.items() if value not in ("", [], {})}


def _model_followup_task_core_step_runtime_trace(
    task_core: Mapping[str, Any],
    step_id: str,
) -> dict[str, Any]:
    clean_step_id = str(step_id or "").strip()
    if not clean_step_id or not isinstance(task_core, Mapping):
        return {}
    for todo in _mapping_list(task_core.get("todos")):
        if str(todo.get("step_id") or "").strip() != clean_step_id:
            continue
        metadata = todo.get("metadata") if isinstance(todo.get("metadata"), Mapping) else {}
        trace = _runtime_trace_metadata_from_mapping(metadata)
        if trace:
            return trace
    for checkpoint in _mapping_list(task_core.get("checkpoints")):
        if str(checkpoint.get("after_step_id") or "").strip() != clean_step_id:
            continue
        payload = checkpoint.get("payload") if isinstance(checkpoint.get("payload"), Mapping) else {}
        trace = _runtime_trace_metadata_from_mapping(payload)
        if trace:
            return trace
    return {}


def _model_replan_followup_context_payload(
    replan_payloads: list[dict[str, Any]],
    *,
    allowed_tools: list[str],
    timeline: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    allowed = {str(tool or "").strip() for tool in allowed_tools if str(tool or "").strip()}
    requests: list[dict[str, Any]] = []
    fallback_candidates: list[str] = []
    failed_tools: list[str] = []
    triggers: list[str] = []
    for payload in replan_payloads:
        if not isinstance(payload, Mapping):
            continue
        metadata = (
            dict(payload.get("metadata"))
            if isinstance(payload.get("metadata"), Mapping)
            else {}
        )
        request = {
            "request_id": str(payload.get("request_id") or "").strip(),
            "trigger": str(payload.get("trigger") or "").strip(),
            "source": str(payload.get("source") or "").strip(),
            "run_id": str(payload.get("run_id") or "").strip(),
            "decision_id": str(payload.get("decision_id") or "").strip(),
            "plan_id": str(payload.get("plan_id") or "").strip(),
            "source_step_id": str(payload.get("source_step_id") or "").strip(),
            "source_tool_name": str(payload.get("source_tool_name") or "").strip(),
            "source_tool_call_id": str(
                payload.get("source_tool_call_id") or ""
            ).strip(),
            "recovery_observation_tool_call_id": str(
                payload.get("recovery_observation_tool_call_id") or ""
            ).strip(),
            "target_capability_id": str(payload.get("target_capability_id") or "").strip(),
            "condition": str(payload.get("condition") or "").strip(),
            "reason": str(payload.get("reason") or "").strip(),
            "failure_event_type": str(payload.get("failure_event_type") or "").strip(),
            "failure_detail": str(payload.get("failure_detail") or "").strip(),
            "fallback_tools": _string_list(payload.get("fallback_tools")),
            "recovery_actions": _mapping_list(metadata.get("recovery_actions")),
            "recommended_tools": _string_list(metadata.get("recommended_tools")),
            "replan_prompt": str(payload.get("replan_prompt") or "").strip(),
            "metadata": metadata,
            "grounded_observation": (
                dict(payload.get("grounded_observation"))
                if isinstance(payload.get("grounded_observation"), Mapping)
                else {}
            ),
            "grounded_observations": [
                dict(item)
                for item in _mapping_list(payload.get("grounded_observations"))
            ],
            **_replan_recovery_target(payload),
        }
        requests.append(request)
        failed_tools.append(request["source_tool_name"])
        fallback_candidates.extend(request["fallback_tools"])
        triggers.append(request["trigger"])
    if not requests:
        return {}
    fallback_candidates = _ordered_text_list(fallback_candidates)
    allowed_fallback_tools = [
        tool for tool in fallback_candidates if not allowed or tool in allowed
    ]
    triggers = _ordered_text_list(triggers)
    first = requests[0]
    payload = {
        "source": "runtime_planner",
        "status": "ready",
        "planning_reason": _runtime_replan_planning_reason(triggers),
        "replan_request_count": len(requests),
        "replan_requests": requests,
        "fallback_tools": allowed_fallback_tools,
        "fallback_tool_candidates": fallback_candidates,
        "failed_tools": _ordered_text_list(failed_tools),
        "triggers": triggers,
        "trigger": first.get("trigger", ""),
        "failure_detail": first.get("failure_detail", ""),
        "source_tool_name": first.get("source_tool_name", ""),
        "target_capability_id": first.get("target_capability_id", ""),
    }
    recovery_targets = _runtime_replan_recovery_targets(requests)
    if recovery_targets:
        payload["recovery_targets"] = recovery_targets
        for key in ("target_app_name", "target_app_query", "target_search_text"):
            value = str(recovery_targets[0].get(key) or "").strip()
            if value:
                payload[key] = value
    recovery_observations = _runtime_replan_recovery_observations(
        requests,
        timeline or [],
    )
    if recovery_observations:
        payload["recovery_observations"] = recovery_observations
        payload["content_snapshots"] = recovery_observations
        payload["content_snapshot"] = recovery_observations[-1]
        payload["recovery_observation_tools"] = _ordered_text_list(
            [
                str(observation.get("source_tool") or "").strip()
                for observation in recovery_observations
                if str(observation.get("source_tool") or "").strip()
            ]
        )
    for key in ("request_id", "decision_id", "plan_id", "core_id", "run_id", "task_id"):
        value = str((replan_payloads[0] if replan_payloads else {}).get(key) or "").strip()
        if value:
            payload[key] = value
    task_progress = _runtime_replan_task_progress_summary(
        replan_payloads,
        timeline or [],
    )
    if task_progress:
        payload["task_progress"] = task_progress
    task_core = _runtime_replan_task_core_payload(replan_payloads, timeline or [])
    if not task_core:
        task_core = _runtime_replan_task_core_context_payload(replan_payloads)
    if task_core:
        payload["task_core"] = task_core
        followup_target = _model_followup_target_from_task_core_context(payload)
        if followup_target:
            normalized_target = _model_followup_target_payload(
                {"followup_target": followup_target},
                allowed,
            )
            payload["followup_target"] = normalized_target or followup_target
    capability_recovery = _runtime_replan_capability_recovery(
        requests,
        allowed_tools=allowed_tools,
    )
    if capability_recovery:
        payload["capability_recovery"] = capability_recovery
    recovery_actions = _runtime_replan_recovery_actions(
        requests,
        allowed_tools=allowed_tools,
    )
    if recovery_actions:
        payload["recovery_actions"] = recovery_actions
    pending_plan_steps = _runtime_replan_pending_code_repair_steps(
        requests,
        allowed_tools=allowed,
    )
    if pending_plan_steps:
        payload["pending_plan_steps"] = pending_plan_steps
    return payload


def _runtime_replan_task_core_context_payload(
    replan_payloads: list[dict[str, Any]],
) -> dict[str, Any]:
    for payload in replan_payloads:
        if not isinstance(payload, Mapping):
            continue
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), Mapping) else {}
        context = (
            metadata.get("task_core_context")
            if isinstance(metadata.get("task_core_context"), Mapping)
            else {}
        )
        if not context:
            continue
        workspace_items = _mapping_list(context.get("workspace_items"))
        workspace = {
            "workspace_id": str(context.get("workspace_id") or "").strip(),
            "title": str(context.get("workspace_title") or "").strip(),
            "items": [dict(item) for item in workspace_items],
        }
        return {
            "core_id": str(context.get("core_id") or "").strip(),
            "workspace": {
                key: value
                for key, value in workspace.items()
                if value not in ("", [], {})
            },
            "todos": [dict(todo) for todo in _mapping_list(context.get("todos"))],
            "checkpoints": [
                dict(checkpoint)
                for checkpoint in _mapping_list(context.get("checkpoints"))
            ],
            "replan_signals": [
                dict(signal)
                for signal in _mapping_list(context.get("replan_signals"))
            ],
        }
    return {}


def _runtime_replan_pending_code_repair_steps(
    requests: Iterable[Mapping[str, Any]],
    *,
    allowed_tools: set[str],
) -> list[dict[str, Any]]:
    steps: list[dict[str, Any]] = []
    for request in requests:
        if not _runtime_replan_request_needs_code_repair(request):
            continue
        source_step = str(request.get("source_step_id") or "verification").strip()
        suffix = _runtime_replan_safe_step_suffix(source_step)
        request_id = str(request.get("request_id") or "").strip()
        trigger = str(request.get("trigger") or "").strip()
        repair_step_id = f"repair-after-{suffix}"
        verify_step_id = f"verify-after-{suffix}"
        command = _runtime_replan_verification_command(request)
        common = {
            "replan_request_id": request_id,
            "replan_trigger": trigger,
            "decision_id": str(request.get("decision_id") or "").strip(),
            "plan_id": str(request.get("plan_id") or "").strip(),
            "runtime_doctrine": "discover_operate_verify",
        }
        if "workspace.write_patch" in allowed_tools:
            steps.append(
                {
                    **common,
                    "step_id": repair_step_id,
                    "title": "Repair code after failed verification",
                    "tool_name": "workspace.write_patch",
                    "capability_id": "file.workspace_write",
                    "action": "apply_patch",
                    "input_preview": {
                        "mode": "fix",
                        "patch_source": "model_after_failed_verification",
                        "failure_detail": str(request.get("failure_detail") or "").strip(),
                    },
                    "risk_level": "high",
                    "approval_required": True,
                    "runtime_stage": "operate",
                    "runtime_role": "apply_patch",
                    "requires_observation": False,
                    "requires_post_action_verification": True,
                    "task_todo": {
                        "todo_id": f"todo-{repair_step_id}",
                        "step_id": repair_step_id,
                        "title": "Repair code after failed verification",
                        "status": "pending",
                        "tool_name": "workspace.write_patch",
                        "capability_id": "file.workspace_write",
                        "approval_required": True,
                    },
                }
            )
        if command and "terminal.run" in allowed_tools:
            verify_step: dict[str, Any] = {
                **common,
                "step_id": verify_step_id,
                "title": "Verify repaired code",
                "tool_name": "terminal.run",
                "capability_id": "terminal.execution",
                "action": "run_verification",
                "input_preview": {"command": command},
                "risk_level": "high",
                "approval_required": True,
                "runtime_stage": "verify",
                "runtime_role": "verify_result",
                "requires_observation": True,
                "requires_post_action_verification": False,
                "task_todo": {
                    "todo_id": f"todo-{verify_step_id}",
                    "step_id": verify_step_id,
                    "title": "Verify repaired code",
                    "status": "pending",
                    "tool_name": "terminal.run",
                    "capability_id": "terminal.execution",
                    "approval_required": True,
                },
            }
            if any(step.get("step_id") == repair_step_id for step in steps):
                verify_step["depends_on"] = [repair_step_id]
            steps.append(verify_step)
        if steps:
            break
    return [
        {key: value for key, value in step.items() if value not in ("", [], {})}
        for step in steps
    ]


def _runtime_direct_recovery_root_identity(
    timeline: Sequence[Mapping[str, Any]],
    *,
    run_id: str,
    source_tool_call_id: str,
    source_tool_name: str,
    source_result: Mapping[str, Any],
    source_step_ids: Iterable[str],
    allow_planner_dependency_ancestor: bool = False,
    required_target_capabilities: Iterable[str] = (),
) -> dict[str, str]:
    """Return one exact, provider-attested planner source for a direct retry."""

    clean_run_id = str(run_id or "").strip()
    clean_call_id = str(source_tool_call_id or "").strip()
    clean_tool = str(source_tool_name or "").strip()
    declared_steps = {
        str(step_id or "").strip()
        for step_id in source_step_ids
        if str(step_id or "").strip()
    }
    if (
        not clean_run_id
        or not clean_call_id
        or not clean_tool
        or not declared_steps
        or not _runtime_execution_provider_identity(source_result)
    ):
        return {}
    winner: Mapping[str, Any] | None = None
    winner_index = -1
    for index, raw_event in enumerate(timeline):
        if not isinstance(raw_event, Mapping):
            continue
        payload = raw_event.get("payload")
        event = (
            {**dict(payload), **dict(raw_event)}
            if isinstance(payload, Mapping)
            else dict(raw_event)
        )
        if str(event.get("event") or event.get("event_type") or "").strip() not in {
            "agent.tool.call",
            "agent.tool.failed",
            "agent.tool.skipped",
        }:
            continue
        if str(event.get("run_id") or "").strip() != clean_run_id:
            continue
        if str(event.get("tool_call_id") or "").strip() != clean_call_id:
            continue
        winner = event
        winner_index = index
        break
    if winner is None:
        return {}
    result = winner.get("result")
    plan_id = str(winner.get("plan_id") or "").strip()
    step_id = str(
        winner.get("step_id") or winner.get("planner_step_id") or ""
    ).strip()
    source_is_declared = step_id in declared_steps
    if (
        not source_is_declared
        and allow_planner_dependency_ancestor
        and winner_index >= 0
    ):
        source_is_declared = _runtime_planner_dependency_ancestor_matches(
            timeline[:winner_index],
            run_id=clean_run_id,
            plan_id=plan_id,
            source_step_id=step_id,
            source_tool_name=clean_tool,
            target_step_ids=declared_steps,
            required_target_capabilities=required_target_capabilities,
        )
    if (
        str(winner.get("tool") or winner.get("detail") or "").strip()
        != clean_tool
        or not isinstance(result, Mapping)
        or result != source_result
        or not source_is_declared
        or not _runtime_owned_terminal_event(
            winner,
            result,
            run_id=clean_run_id,
            plan_id=plan_id,
        )
    ):
        return {}
    provider = _runtime_execution_provider_identity(result)
    return {
        "root_plan_id": plan_id,
        "root_source_step_id": step_id,
        "root_provider_kind": provider["provider_kind"],
        "root_provider_id": provider["provider_id"],
    }


_RUNTIME_PLANNER_GRAPH_BOOL_FIELDS = (
    "continue_to_model",
    "requires_observation",
    "requires_post_action_verification",
)

_RUNTIME_PLANNER_GRAPH_AUTHORITY_BOOL_FIELDS = (
    "approved",
    "approval_resume_result_canonical",
    "approved_by_replan_recovery_action",
    "goal_completion_authority",
    "observation_only",
)

_RUNTIME_PLANNER_GRAPH_APPROVAL_TEXT_FIELDS = (
    "approval_id",
    "approval_generation_id",
    "approval_claim_id",
    "approval_request_fingerprint",
    "approval_status",
    "source_approval_id",
    "expected_approval_id",
    "parent_approval_id",
    "approval_source",
    "approval_authority",
    "approval_reason",
    "approval_policy",
    "approval_mode",
    "approval_scope",
)

_RUNTIME_PLANNER_GRAPH_APPROVAL_MAPPING_FIELDS = (
    "approval",
    "approval_context",
    "approval_lineage",
    "approval_metadata",
)

_RUNTIME_PLANNER_ROUTE_AUTHORITY_TEXT_FIELDS = (
    "route_id",
    "tool_name",
    "requested_mode",
    "desktop_execution_session_policy",
    "desktop_session_kind",
    "desktop_backend_kind",
    "fallback_mode",
    "source",
    "delivery_mode",
    "transport",
    "transport_kind",
    "selected_transport",
    "selected_transport_kind",
    "selected_transport_id",
    "mcp_tool",
    "endpoint_origin",
    "endpoint_path",
)

_RUNTIME_PLANNER_ROUTE_AUTHORITY_BOOL_FIELDS = (
    "can_execute",
    "can_auto_start",
    "provider_execution_required",
    "sandbox_required",
    "background_desktop_preferred",
    "isolated_desktop_preferred",
    "foreground_takeover_allowed",
    "user_foreground_takeover_risk",
    "requires_user_foreground_session",
    "foreground_mutation_supported",
    "keyboard_mouse_capture_supported",
    "desktop_session_isolated",
    "foreground_takeover_required",
    "desktop_backend_is_loopback",
    "desktop_backend_ready_for_public_release",
    "requires_real_virtual_desktop_backend",
    "simulated_desktop_provider",
    "background_only",
    "background_execution_required",
    "foreground_execution_required",
)

_RUNTIME_PLANNER_ROUTE_AUTHORITY_MAPPING_FIELDS = (
    "provider_contract",
    "provider_transport",
    "desktop_execution_provider_transport",
    "transport_authority",
)

_RUNTIME_PLANNER_ROUTE_VOLATILE_TEXT_FIELDS = (
    "status",
    "provider_readiness_status",
    "reason",
)

_RUNTIME_PLANNER_ROUTE_VOLATILE_TEXT_LIST_FIELDS = (
    "blocking_conditions",
    "provider_contract_blocking_conditions",
)

_RUNTIME_PLANNER_CANONICAL_INVALID = object()


def _canonical_runtime_planner_json_value(value: Any) -> Any:
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, Mapping):
        if any(not isinstance(key, str) for key in value):
            return _RUNTIME_PLANNER_CANONICAL_INVALID
        payload: dict[str, Any] = {}
        for key in sorted(value):
            normalized = _canonical_runtime_planner_json_value(value[key])
            if normalized is _RUNTIME_PLANNER_CANONICAL_INVALID:
                return _RUNTIME_PLANNER_CANONICAL_INVALID
            payload[key] = normalized
        return payload
    if isinstance(value, (list, tuple)):
        payload = []
        for item in value:
            normalized = _canonical_runtime_planner_json_value(item)
            if normalized is _RUNTIME_PLANNER_CANONICAL_INVALID:
                return _RUNTIME_PLANNER_CANONICAL_INVALID
            payload.append(normalized)
        return payload
    return _RUNTIME_PLANNER_CANONICAL_INVALID


def _canonical_runtime_planner_desktop_execution_route(
    value: Any,
) -> dict[str, Any] | None:
    if value is None:
        route: Mapping[str, Any] = {}
    elif isinstance(value, Mapping):
        route = value
    else:
        return None

    known_fields = {
        *_RUNTIME_PLANNER_ROUTE_AUTHORITY_TEXT_FIELDS,
        *_RUNTIME_PLANNER_ROUTE_AUTHORITY_BOOL_FIELDS,
        *_RUNTIME_PLANNER_ROUTE_AUTHORITY_MAPPING_FIELDS,
        *_RUNTIME_PLANNER_ROUTE_VOLATILE_TEXT_FIELDS,
        *_RUNTIME_PLANNER_ROUTE_VOLATILE_TEXT_LIST_FIELDS,
        "selected_provider_kind",
        "selected_provider_id",
        "provider_kind",
        "provider_id",
    }
    if any(not isinstance(key, str) or key not in known_fields for key in route):
        # A new route field may carry provider or foreground authority. Do not
        # silently dedupe it until its immutable/volatile semantics are known.
        return None

    for key in _RUNTIME_PLANNER_ROUTE_VOLATILE_TEXT_FIELDS:
        if key in route and not isinstance(route.get(key), str):
            return None
    for key in _RUNTIME_PLANNER_ROUTE_VOLATILE_TEXT_LIST_FIELDS:
        if key not in route:
            continue
        values = route.get(key)
        if not isinstance(values, (list, tuple)) or any(
            not isinstance(item, str) for item in values
        ):
            return None

    canonical: dict[str, Any] = {}
    for key in _RUNTIME_PLANNER_ROUTE_AUTHORITY_TEXT_FIELDS:
        raw = route.get(key)
        if key in route and not isinstance(raw, str):
            return None
        canonical[key] = raw.strip() if isinstance(raw, str) else ""
    for key in _RUNTIME_PLANNER_ROUTE_AUTHORITY_BOOL_FIELDS:
        raw = route.get(key)
        if key in route and raw is not None and not isinstance(raw, bool):
            return None
        canonical[key] = raw if isinstance(raw, bool) else None
    for key in _RUNTIME_PLANNER_ROUTE_AUTHORITY_MAPPING_FIELDS:
        raw = route.get(key)
        if key in route and not isinstance(raw, Mapping):
            return None
        normalized = _canonical_runtime_planner_json_value(raw or {})
        if normalized is _RUNTIME_PLANNER_CANONICAL_INVALID:
            return None
        canonical[key] = normalized

    for canonical_key, aliases in (
        ("selected_provider_kind", ("selected_provider_kind", "provider_kind")),
        ("selected_provider_id", ("selected_provider_id", "provider_id")),
    ):
        values: set[str] = set()
        for key in aliases:
            raw = route.get(key)
            if key in route and not isinstance(raw, str):
                return None
            if isinstance(raw, str) and raw.strip():
                values.add(raw.strip())
        if len(values) > 1:
            return None
        canonical[canonical_key] = next(iter(values), "")
    return canonical


def _canonical_runtime_planner_request_graph(
    requests: Sequence[Mapping[str, Any]],
    *,
    plan_id: str,
    decision_id: str,
) -> list[dict[str, Any]] | None:
    """Canonicalize immutable execution semantics, excluding live overlays."""

    clean_plan_id = str(plan_id or "").strip()
    clean_decision_id = str(decision_id or "").strip()
    if not clean_plan_id or not clean_decision_id or not requests:
        return None
    canonical: list[dict[str, Any]] = []
    seen_step_ids: set[str] = set()
    for request in requests:
        if not isinstance(request, Mapping):
            return None
        step_values = {
            str(request.get(key) or "").strip()
            for key in ("step_id", "planner_step_id")
            if str(request.get(key) or "").strip()
        }
        tool_values = {
            str(request.get(key) or "").strip()
            for key in ("tool_name", "tool")
            if str(request.get(key) or "").strip()
        }
        step_id = next(iter(step_values), "")
        tool_name = next(iter(tool_values), "")
        request_id = str(request.get("request_id") or "").strip()
        request_plan_id = str(request.get("plan_id") or "").strip()
        request_decision_id = str(request.get("decision_id") or "").strip()
        tool_plan_id = str(request.get("tool_plan_id") or "").strip()
        capability_id = str(request.get("capability_id") or "").strip()
        source = str(request.get("source") or "").strip()
        request_input = request.get("input")
        dependencies = request.get("depends_on") or []
        desktop_execution_route = (
            _canonical_runtime_planner_desktop_execution_route(
                request.get("desktop_execution_route")
            )
        )
        approval_required_values: set[bool] = set()
        for key in ("approval_required", "requires_approval"):
            raw = request.get(key)
            if key in request and not isinstance(raw, bool):
                return None
            if isinstance(raw, bool):
                approval_required_values.add(raw)
        if len(approval_required_values) > 1:
            return None
        approval_required = next(iter(approval_required_values), False)
        known_approval_fields = {
            "approval_required",
            "requires_approval",
            "approval_ids",
            *_RUNTIME_PLANNER_GRAPH_AUTHORITY_BOOL_FIELDS,
            *_RUNTIME_PLANNER_GRAPH_APPROVAL_TEXT_FIELDS,
            *_RUNTIME_PLANNER_GRAPH_APPROVAL_MAPPING_FIELDS,
        }
        if (
            len(step_values) != 1
            or len(tool_values) != 1
            or not request_id
            or not tool_plan_id
            or not capability_id
            or request_plan_id != clean_plan_id
            or request_decision_id != clean_decision_id
            or source not in {"runtime_planner", "runtime_verification"}
            or not isinstance(request_input, Mapping)
            or not isinstance(dependencies, (list, tuple))
            or any(not str(value or "").strip() for value in dependencies)
            or step_id in seen_step_ids
            or any(
                key in request and not isinstance(request.get(key), bool)
                for key in _RUNTIME_PLANNER_GRAPH_BOOL_FIELDS
            )
            or desktop_execution_route is None
            or any(
                key in request
                and request.get(key) is not None
                and not isinstance(request.get(key), bool)
                for key in _RUNTIME_PLANNER_GRAPH_AUTHORITY_BOOL_FIELDS
            )
            or any(
                key in request
                and request.get(key) is not None
                and not isinstance(request.get(key), str)
                for key in _RUNTIME_PLANNER_GRAPH_APPROVAL_TEXT_FIELDS
            )
            or any(
                isinstance(key, str)
                and "approval" in key
                and key not in known_approval_fields
                for key in request
            )
        ):
            return None
        approval_ids = request.get("approval_ids") or []
        if not isinstance(approval_ids, (list, tuple)) or any(
            not isinstance(value, str) or not value.strip()
            for value in approval_ids
        ):
            return None
        approval_mappings: dict[str, Any] = {}
        for key in _RUNTIME_PLANNER_GRAPH_APPROVAL_MAPPING_FIELDS:
            raw = request.get(key)
            if key in request and raw is not None and not isinstance(raw, Mapping):
                return None
            normalized = _canonical_runtime_planner_json_value(raw or {})
            if normalized is _RUNTIME_PLANNER_CANONICAL_INVALID:
                return None
            approval_mappings[key] = normalized
        clean_dependencies = sorted(
            {str(value or "").strip() for value in dependencies}
        )
        if step_id in clean_dependencies:
            return None
        seen_step_ids.add(step_id)
        item: dict[str, Any] = {
            "request_id": request_id,
            "decision_id": request_decision_id,
            "plan_id": request_plan_id,
            "tool_plan_id": tool_plan_id,
            "step_id": step_id,
            "tool_name": tool_name,
            "input": dict(request_input),
            "depends_on": clean_dependencies,
            "source": source,
            "capability_id": capability_id,
            "protocol": str(request.get("protocol") or "json_fallback").strip(),
            "planning_reason": str(request.get("planning_reason") or "").strip(),
            "intent_kind": str(request.get("intent_kind") or "").strip(),
            "core_id": str(request.get("core_id") or "").strip(),
            "workspace_id": str(request.get("workspace_id") or "").strip(),
            "runtime_stage": str(request.get("runtime_stage") or "").strip(),
            "runtime_role": str(request.get("runtime_role") or "").strip(),
            "risk_level": str(request.get("risk_level") or "").strip(),
            "policy_reason": str(request.get("policy_reason") or "").strip(),
            "presentation": str(request.get("presentation") or "").strip(),
            "approval_required": approval_required,
            "approval_ids": [value.strip() for value in approval_ids],
            "desktop_execution_route": desktop_execution_route,
        }
        for key in _RUNTIME_PLANNER_GRAPH_BOOL_FIELDS:
            item[key] = request.get(key) is True
        for key in _RUNTIME_PLANNER_GRAPH_AUTHORITY_BOOL_FIELDS:
            value = request.get(key)
            item[key] = value if isinstance(value, bool) else None
        for key in _RUNTIME_PLANNER_GRAPH_APPROVAL_TEXT_FIELDS:
            value = request.get(key)
            item[key] = value.strip() if isinstance(value, str) else ""
        item.update(approval_mappings)
        for key in (
            "fallback_tools",
            "input_bindings",
            "replan_triggers",
            "task_verification_targets",
            "verification_targets",
        ):
            value = request.get(key) or []
            if not isinstance(value, (list, tuple)):
                return None
            item[key] = list(value)
        for key in (
            "action_target",
            "desktop_execution_policy",
            "desktop_loop",
            "observation_evidence",
            "observation_retry",
        ):
            value = request.get(key) or {}
            if not isinstance(value, Mapping):
                return None
            item[key] = dict(value)
        canonical.append(item)

    if any(
        dependency not in seen_step_ids
        for request in canonical
        for dependency in request["depends_on"]
    ):
        return None
    by_step_id = {request["step_id"]: request for request in canonical}
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(step_id: str) -> bool:
        if step_id in visited:
            return True
        if step_id in visiting:
            return False
        visiting.add(step_id)
        if not all(visit(dependency) for dependency in by_step_id[step_id]["depends_on"]):
            return False
        visiting.remove(step_id)
        visited.add(step_id)
        return True

    if not all(visit(step_id) for step_id in by_step_id):
        return None
    return sorted(canonical, key=lambda request: request["step_id"])


def _runtime_planner_selection_request_graphs(
    timeline: Sequence[Mapping[str, Any]],
    *,
    run_id: str,
    plan_id: str,
) -> dict[str, list[dict[str, Any]]]:
    clean_run_id = str(run_id or "").strip()
    clean_plan_id = str(plan_id or "").strip()
    if not clean_run_id or not clean_plan_id:
        return {}
    matching: dict[str, list[dict[str, Any]]] = {}
    for raw_event in timeline:
        if not isinstance(raw_event, Mapping):
            continue
        payload = (
            raw_event.get("payload")
            if isinstance(raw_event.get("payload"), Mapping)
            else {}
        )
        event = {**dict(payload), **dict(raw_event)}
        if _runtime_planner_base_event_type(
            str(event.get("event") or event.get("event_type") or "").strip()
        ) != "agent.plan.selection":
            continue
        run_ids = {
            str(source.get("run_id") or "").strip()
            for source in (payload, raw_event)
            if str(source.get("run_id") or "").strip()
        }
        if run_ids != {clean_run_id}:
            continue
        selection_sources = {
            str(source.get(key) or "").strip()
            for source in (payload, raw_event)
            for key in ("selected_source", "selection_source", "source")
            if str(source.get(key) or "").strip()
        }
        if not selection_sources or not selection_sources.issubset(
            {"runtime_planner", "runtime_execution_envelope"}
        ):
            continue
        envelope_candidates = [
            source.get(key)
            for source in (payload, raw_event)
            for key in (
                "yachiyo_execution_envelope",
                "execution_envelope",
                "runtime_execution_envelope",
            )
            if isinstance(source.get(key), Mapping)
        ]
        if not envelope_candidates:
            continue
        envelope_keys = {
            json.dumps(
                dict(envelope),
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            for envelope in envelope_candidates
        }
        if len(envelope_keys) != 1:
            continue
        envelope = envelope_candidates[0]
        envelope_id = str(envelope.get("envelope_id") or "").strip()
        envelope_decision_id = str(envelope.get("decision_id") or "").strip()
        envelope_plan_id = str(envelope.get("plan_id") or "").strip()
        envelope_source = str(envelope.get("source") or "").strip()
        event_plan_id = str(event.get("plan_id") or "").strip()
        event_decision_id = str(event.get("decision_id") or "").strip()
        requests = envelope.get("requests")
        if (
            not envelope_id
            or not envelope_decision_id
            or envelope_plan_id != clean_plan_id
            or envelope_source != "runtime_planner"
            or (event_plan_id and event_plan_id != clean_plan_id)
            or (event_decision_id and event_decision_id != envelope_decision_id)
            or not isinstance(requests, list)
            or not requests
            or any(not isinstance(request, Mapping) for request in requests)
        ):
            continue
        graph = _canonical_runtime_planner_request_graph(
            requests,
            plan_id=clean_plan_id,
            decision_id=envelope_decision_id,
        )
        if graph is None:
            # A matching trusted selection snapshot with malformed or unknown
            # execution authority cannot be ignored in favour of an older
            # valid snapshot. The graph proof is now ambiguous, so fail closed.
            return {}
        canonical = json.dumps(
            {
                "envelope_id": envelope_id,
                "decision_id": envelope_decision_id,
                "plan_id": envelope_plan_id,
                "source": envelope_source,
                "requests": graph,
            },
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        matching[canonical] = graph
    return matching


def _runtime_planner_dependency_ancestor_matches(
    timeline: Sequence[Mapping[str, Any]],
    *,
    run_id: str,
    plan_id: str,
    source_step_id: str,
    source_tool_name: str,
    target_step_ids: Iterable[str],
    required_target_capabilities: Iterable[str],
) -> bool:
    """Prove that a failed step is an immutable planner dependency.

    Goal criteria name the step that fulfils the user-visible effect, not
    every prerequisite needed to reach it. An owned-window launch may recover
    only when the Runtime's recorded plan proves that the launch step is an
    ancestor of that exact criterion source step. Public/model text and tool
    results cannot mint this dependency edge.
    """

    clean_run_id = str(run_id or "").strip()
    clean_plan_id = str(plan_id or "").strip()
    clean_source_step_id = str(source_step_id or "").strip()
    clean_source_tool_name = str(source_tool_name or "").strip()
    clean_targets = {
        str(step_id or "").strip()
        for step_id in target_step_ids
        if str(step_id or "").strip()
    }
    target_capabilities = {
        str(capability or "").strip()
        for capability in required_target_capabilities
        if str(capability or "").strip()
    }
    if not all(
        (
            clean_run_id,
            clean_plan_id,
            clean_source_step_id,
            clean_source_tool_name,
            clean_targets,
            target_capabilities,
        )
    ):
        return False

    matching_request_sets = _runtime_planner_selection_request_graphs(
        timeline,
        run_id=clean_run_id,
        plan_id=clean_plan_id,
    )
    if len(matching_request_sets) != 1:
        return False

    requests = next(iter(matching_request_sets.values()))
    by_step_id: dict[str, Mapping[str, Any]] = {}
    for request in requests:
        step_id = str(
            request.get("step_id") or request.get("planner_step_id") or ""
        ).strip()
        tool_name = str(
            request.get("tool_name") or request.get("tool") or ""
        ).strip()
        request_plan_id = str(request.get("plan_id") or "").strip()
        source = str(request.get("source") or "").strip()
        dependencies = request.get("depends_on") or []
        if (
            not step_id
            or not tool_name
            or step_id in by_step_id
            or (request_plan_id and request_plan_id != clean_plan_id)
            or source not in {"runtime_planner", "runtime_verification"}
            or not isinstance(dependencies, (list, tuple))
            or any(not str(value or "").strip() for value in dependencies)
        ):
            return False
        by_step_id[step_id] = request

    source_request = by_step_id.get(clean_source_step_id)
    if not isinstance(source_request, Mapping) or str(
        source_request.get("tool_name") or source_request.get("tool") or ""
    ).strip() != clean_source_tool_name:
        return False

    eligible_targets = {
        target
        for target in clean_targets
        if target in by_step_id
        and target_capabilities.issubset(
            set(
                capability_ids_for_tool(
                    str(
                        by_step_id[target].get("tool_name")
                        or by_step_id[target].get("tool")
                        or ""
                    ).strip()
                )
            )
        )
    }
    if not eligible_targets or clean_source_step_id in eligible_targets:
        return False

    def depends_on_source(step_id: str, visiting: frozenset[str]) -> bool:
        if step_id == clean_source_step_id:
            return True
        if step_id in visiting:
            return False
        request = by_step_id.get(step_id)
        if not isinstance(request, Mapping):
            return False
        dependencies = {
            str(value or "").strip()
            for value in request.get("depends_on") or []
            if str(value or "").strip()
        }
        if any(dependency not in by_step_id for dependency in dependencies):
            return False
        next_visiting = frozenset((*visiting, step_id))
        return any(
            depends_on_source(dependency, next_visiting)
            for dependency in dependencies
        )

    return any(
        depends_on_source(target, frozenset()) for target in eligible_targets
    )


def _runtime_background_window_resume_contract(
    results: Sequence[OutcomeLoopResult],
    planned_requests: Sequence[Mapping[str, Any]],
    *,
    timeline: Sequence[Mapping[str, Any]],
    run_id: str,
) -> tuple[str, list[dict[str, Any]]]:
    """Return the exact recovered source and its transitive plan descendants."""

    candidates = []
    for result in results:
        recovery = result.recovery_action_result
        plan = result.recovery_plan
        if (
            result.disposition is OutcomeLoopDisposition.CONTINUE_PLAN
            and result.outcome.status is OutcomeStatus.FAILED
            and result.outcome.tool_name == "app.open"
            and plan is not None
            and plan.action == "materialize_background_window"
            and plan.strategy_id == "materialize-background-window"
            and plan.recovery_hint == "materialize_background_window"
            and recovery is not None
            and recovery.disposition is RecoveryActionDisposition.CONTINUE_PLAN
            and recovery.reason == "background_window_materialized"
            and recovery.attempts
        ):
            candidates.append(result)
    if len(candidates) != 1:
        return "", []
    result = candidates[0]
    plan = result.recovery_plan
    assert plan is not None
    source_tool_call_id = str(result.source_tool_call_id or "").strip()
    subgoal_candidates: list[Mapping[str, Any]] = []
    for raw_event in timeline:
        if not isinstance(raw_event, Mapping):
            continue
        payload = (
            raw_event.get("payload")
            if isinstance(raw_event.get("payload"), Mapping)
            else {}
        )
        event = {**dict(payload), **dict(raw_event)}
        subgoal = event.get("subgoal")
        if (
            str(event.get("event") or event.get("event_type") or "").strip()
            == "agent.goal.subgoal.opened"
            and str(event.get("detail") or "").strip()
            == "materialize_background_window"
            and str(event.get("run_id") or "").strip()
            == str(run_id or "").strip()
            and str(event.get("source_tool_call_id") or "").strip()
            == source_tool_call_id
            and str(event.get("source") or "").strip()
            == "runtime_goal_coordinator"
            and str(event.get("actor") or "").strip() == "native_runtime"
            and str(event.get("execution_authority") or "").strip()
            == "runtime_goal_coordinator"
            and str(event.get("visibility") or "").strip() == "internal"
            and str(event.get("status") or "").strip() == "opened"
            and isinstance(subgoal, Mapping)
            and str(subgoal.get("action") or "").strip()
            == "materialize_background_window"
            and str(subgoal.get("source_tool_call_id") or "").strip()
            == source_tool_call_id
            and str(subgoal.get("contract_id") or "").strip()
            == str(event.get("contract_id") or "").strip()
            and str(subgoal.get("criterion_id") or "").strip()
            == str(event.get("criterion_id") or "").strip()
            and str(subgoal.get("subgoal_id") or "").strip()
        ):
            subgoal_candidates.append(event)
    if len(subgoal_candidates) != 1:
        return "", []
    goal_identity = subgoal_candidates[0]
    subgoal = goal_identity["subgoal"]
    plan_id = str(goal_identity.get("root_plan_id") or "").strip()
    source_step_id = str(
        goal_identity.get("root_source_step_id") or ""
    ).strip()
    if not all(
        (
            plan_id,
            source_step_id,
            str(goal_identity.get("root_provider_kind") or "").strip(),
            str(goal_identity.get("root_provider_id") or "").strip(),
        )
    ):
        return "", []
    completed_recovery_events = [
        event
        for raw_event in timeline
        if isinstance(raw_event, Mapping)
        for event in (
            {
                **(
                    dict(raw_event.get("payload"))
                    if isinstance(raw_event.get("payload"), Mapping)
                    else {}
                ),
                **dict(raw_event),
            },
        )
        if str(event.get("event") or event.get("event_type") or "").strip()
        == "agent.recovery.completed"
        and str(event.get("source_tool_call_id") or "").strip()
        == source_tool_call_id
        and str(event.get("scope_id") or "").strip() == plan.scope_id
        and str(event.get("strategy_id") or "").strip() == plan.strategy_id
        and str(event.get("action") or "").strip() == plan.action
        and str(event.get("goal_contract_id") or "").strip()
        == str(subgoal.get("contract_id") or "").strip()
        and str(event.get("goal_criterion_id") or "").strip()
        == str(subgoal.get("criterion_id") or "").strip()
        and str(event.get("goal_subgoal_id") or "").strip()
        == str(subgoal.get("subgoal_id") or "").strip()
        and event.get("root_goal_unchanged") is True
        and str(event.get("recovery_owner") or "").strip() == "coordinator"
        and str(event.get("visibility") or "").strip() == "internal"
        and str(event.get("status") or "").strip() == "completed"
        and str(event.get("result_disposition") or "").strip()
        == RecoveryActionDisposition.CONTINUE_PLAN.value
        and str(event.get("result_reason") or "").strip()
        == "background_window_materialized"
        and int(event.get("attempt_count") or 0) == len(recovery.attempts)
    ]
    if len(completed_recovery_events) != 1:
        return "", []
    source_match = _runtime_recovery_executor_terminal_event(
        timeline,
        run_id=str(run_id or "").strip(),
        tool_call_id=source_tool_call_id,
        tool_name="app.open",
    )
    if source_match is None:
        return "", []
    _source_index, source_event = source_match
    source_result = source_event.get("result")
    if (
        not isinstance(source_result, Mapping)
        or source_result != result.outcome.raw
        or str(source_event.get("plan_id") or "").strip() != plan_id
        or str(source_event.get("step_id") or "").strip() != source_step_id
        or str(source_event.get("source") or "").strip() != "runtime_planner"
    ):
        return "", []

    source_request_id = str(source_event.get("request_id") or "").strip()
    source_candidates = [
        (index, request)
        for index, request in enumerate(planned_requests)
        if isinstance(request, Mapping)
        and str(request.get("request_id") or "").strip() == source_request_id
        and str(request.get("step_id") or request.get("planner_step_id") or "").strip()
        == source_step_id
        and str(request.get("tool") or request.get("tool_name") or "").strip()
        == "app.open"
        and str(request.get("plan_id") or "").strip() == plan_id
        and str(request.get("source") or "").strip() == "runtime_planner"
    ]
    if len(source_candidates) != 1:
        return "", []
    source_request_index, source_request = source_candidates[0]
    decision_id = str(source_request.get("decision_id") or "").strip()
    planned_graph = _canonical_runtime_planner_request_graph(
        planned_requests,
        plan_id=plan_id,
        decision_id=decision_id,
    )
    selection_graphs = _runtime_planner_selection_request_graphs(
        timeline,
        run_id=str(run_id or "").strip(),
        plan_id=plan_id,
    )
    if planned_graph is None or len(selection_graphs) != 1:
        return "", []
    selection_graph = next(iter(selection_graphs.values()))
    if json.dumps(
        planned_graph,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ) != json.dumps(
        selection_graph,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ):
        return "", []

    by_step_id = {request["step_id"]: request for request in selection_graph}
    descendant_step_ids = {source_step_id}
    changed = True
    while changed:
        changed = False
        for step_id, request in by_step_id.items():
            if step_id in descendant_step_ids:
                continue
            if descendant_step_ids.intersection(request["depends_on"]):
                descendant_step_ids.add(step_id)
                changed = True
    descendant_step_ids.discard(source_step_id)
    if not descendant_step_ids:
        return "", []
    request_indexes = {
        str(
            request.get("step_id") or request.get("planner_step_id") or ""
        ).strip(): index
        for index, request in enumerate(planned_requests)
        if isinstance(request, Mapping)
    }
    if (
        set(request_indexes) != set(by_step_id)
        or any(
            request_indexes[dependency] >= request_indexes[step_id]
            for step_id, request in by_step_id.items()
            for dependency in request["depends_on"]
        )
        or any(
            request_indexes[step_id] <= source_request_index
            for step_id in descendant_step_ids
        )
        or any(
            dependency not in descendant_step_ids
            and request_indexes[dependency] > source_request_index
            for step_id in descendant_step_ids
            for dependency in by_step_id[step_id]["depends_on"]
        )
    ):
        return "", []
    resume_requests = [
        deepcopy(dict(request))
        for request in planned_requests[source_request_index + 1 :]
        if str(
            request.get("step_id") or request.get("planner_step_id") or ""
        ).strip()
        in descendant_step_ids
    ]
    if len(resume_requests) != len(descendant_step_ids):
        return "", []
    return source_tool_call_id, resume_requests


def _runtime_terminal_winners_for_run(
    timeline: Sequence[Mapping[str, Any]],
    *,
    run_id: str,
) -> list[tuple[int, dict[str, Any]]]:
    winners: list[tuple[int, dict[str, Any]]] = []
    seen_call_ids: set[str] = set()
    clean_run_id = str(run_id or "").strip()
    if not clean_run_id:
        return winners
    for index, raw_event in enumerate(timeline):
        if not isinstance(raw_event, Mapping):
            continue
        payload = raw_event.get("payload")
        event = (
            {**dict(payload), **dict(raw_event)}
            if isinstance(payload, Mapping)
            else dict(raw_event)
        )
        if str(event.get("event") or event.get("event_type") or "").strip() not in {
            "agent.tool.call",
            "agent.tool.failed",
            "agent.tool.skipped",
        }:
            continue
        if str(event.get("run_id") or "").strip() != clean_run_id:
            continue
        tool_call_id = str(event.get("tool_call_id") or "").strip()
        if not tool_call_id or tool_call_id in seen_call_ids:
            continue
        seen_call_ids.add(tool_call_id)
        winners.append((index, event))
    return winners


def _runtime_goal_verification_recovery_lineage(
    followup_context: Mapping[str, Any],
    *,
    contract: GoalContract,
    timeline: list[dict[str, Any]],
    run_id: str,
) -> dict[str, str]:
    if str(followup_context.get("planning_reason") or "").strip() != (
        "planner_replan_after_verification_failed"
    ):
        return {}
    replan_requests = _mapping_list(followup_context.get("replan_requests"))
    candidates = [
        request
        for request in replan_requests
        if str(request.get("trigger") or "").strip() == "verification_failed"
    ]
    if len(candidates) != 1:
        return {}
    replan_request = candidates[0]
    root_verifier_step_id = str(
        replan_request.get("source_step_id") or ""
    ).strip()
    failed_verifier_tool = str(
        replan_request.get("source_tool_name") or ""
    ).strip()
    root_plan_id = str(
        replan_request.get("plan_id")
        or followup_context.get("plan_id")
        or ""
    ).strip()
    replan_request_id = str(replan_request.get("request_id") or "").strip()
    matching_criteria = [
        criterion
        for criterion in contract.criteria
        if root_verifier_step_id in criterion.verifier_step_ids
        and criterion.criterion_id
        in runtime_goal_assessment(contract, timeline).unsatisfied_criterion_ids
    ]
    if (
        len(matching_criteria) != 1
        or not root_verifier_step_id
        or not failed_verifier_tool
        or not root_plan_id
        or not replan_request_id
        or str(replan_request.get("run_id") or "").strip() != run_id
        or str(replan_request.get("plan_id") or "").strip() != root_plan_id
        or str(replan_request.get("source") or "").strip()
        != "runtime_tool_request_runner"
    ):
        return {}
    criterion = matching_criteria[0]
    failed_verifier_event: Mapping[str, Any] | None = None
    failed_index = -1
    winners = _runtime_terminal_winners_for_run(timeline, run_id=run_id)
    for index, event in reversed(winners):
        if str(event.get("detail") or event.get("tool") or "").strip() != (
            failed_verifier_tool
        ):
            continue
        if str(
            event.get("step_id") or event.get("planner_step_id") or ""
        ).strip() != root_verifier_step_id:
            continue
        result = event.get("result") if isinstance(event.get("result"), Mapping) else {}
        if result.get("ok") is not False or not _runtime_owned_terminal_event(
            event,
            result,
            run_id=run_id,
            plan_id=root_plan_id,
        ):
            continue
        tool_call_id = str(event.get("tool_call_id") or "").strip()
        if not tool_call_id:
            continue
        failed_verifier_event = event
        failed_index = index
        break
    if failed_verifier_event is None:
        return {}
    root_source_candidates: list[Mapping[str, Any]] = []
    for index, event in winners:
        if index >= failed_index:
            break
        source_step_id = str(
            event.get("step_id") or event.get("planner_step_id") or ""
        ).strip()
        if source_step_id not in criterion.source_step_ids:
            continue
        tool_name = str(event.get("detail") or event.get("tool") or "").strip()
        if not set(criterion.required_capabilities).issubset(
            set(capability_ids_for_tool(tool_name))
        ):
            continue
        result = event.get("result") if isinstance(event.get("result"), Mapping) else {}
        if (
            result.get("ok") is not True
            or not str(event.get("tool_call_id") or "").strip()
            or not _runtime_owned_terminal_event(
                event,
                result,
                run_id=run_id,
                plan_id=root_plan_id,
            )
        ):
            continue
        root_source_candidates.append(event)
    if not root_source_candidates:
        return {}
    root_source_event = root_source_candidates[-1]
    failed_result = (
        failed_verifier_event.get("result")
        if isinstance(failed_verifier_event.get("result"), Mapping)
        else {}
    )
    root_result = (
        root_source_event.get("result")
        if isinstance(root_source_event.get("result"), Mapping)
        else {}
    )
    failed_provider = _runtime_execution_provider_identity(failed_result)
    root_provider = _runtime_execution_provider_identity(root_result)
    if not root_provider or failed_provider != root_provider:
        return {}
    root_source_step_id = str(
        root_source_event.get("step_id")
        or root_source_event.get("planner_step_id")
        or ""
    ).strip()
    return {
        "criterion_id": criterion.criterion_id,
        "root_source_tool_call_id": str(
            root_source_event.get("tool_call_id") or ""
        ).strip(),
        "root_source_step_id": root_source_step_id,
        "root_verifier_step_id": root_verifier_step_id,
        "root_plan_id": root_plan_id,
        "root_provider_kind": root_provider["provider_kind"],
        "root_provider_id": root_provider["provider_id"],
        "failed_verifier_tool_call_id": str(
            failed_verifier_event.get("tool_call_id") or ""
        ).strip(),
        "failed_verifier_tool": failed_verifier_tool,
        "replan_request_id": replan_request_id,
        "recovery_action": "repair_after_failed_verification",
    }


def _request_matches_runtime_goal_recovery_lineage(
    request: Mapping[str, Any],
    lineage: Mapping[str, str],
) -> bool:
    return bool(
        str(request.get("replan_trigger") or "").strip()
        == "verification_failed"
        and str(request.get("replan_request_id") or "").strip()
        == str(lineage.get("replan_request_id") or "").strip()
        and str(request.get("plan_id") or "").strip()
        == str(lineage.get("root_plan_id") or "").strip()
        and str(request.get("tool") or request.get("tool_name") or "").strip()
    )


def _runtime_replan_request_needs_code_repair(request: Mapping[str, Any]) -> bool:
    if str(request.get("trigger") or "").strip() != "verification_failed":
        return False
    source_tool = str(request.get("source_tool_name") or "").strip()
    capability_id = str(request.get("target_capability_id") or "").strip()
    metadata = request.get("metadata") if isinstance(request.get("metadata"), Mapping) else {}
    intent_kind = str(metadata.get("original_intent_kind") or "").strip()
    fallback_tools = set(_string_list(request.get("fallback_tools")))
    return bool(
        intent_kind == "code_task"
        or source_tool == "terminal.run"
        or capability_id == "terminal.execution"
        or "workspace.write_patch" in fallback_tools
    )


def _runtime_replan_verification_command(request: Mapping[str, Any]) -> str:
    metadata = request.get("metadata") if isinstance(request.get("metadata"), Mapping) else {}
    input_preview = (
        metadata.get("input_preview")
        if isinstance(metadata.get("input_preview"), Mapping)
        else {}
    )
    command = str(input_preview.get("command") or "").strip()
    if command:
        return command
    result_preview = (
        metadata.get("result_preview")
        if isinstance(metadata.get("result_preview"), Mapping)
        else {}
    )
    return str(result_preview.get("command") or "").strip()


def _runtime_replan_safe_step_suffix(value: str) -> str:
    clean = re.sub(r"[^a-zA-Z0-9_-]+", "-", str(value or "").strip()).strip("-")
    return clean[:60] or "verification"


def _timeline_replan_request_payloads(
    timeline: list[dict[str, Any]],
    *,
    start: int = 0,
) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    for event in list(timeline[max(0, int(start or 0)):]):
        if not isinstance(event, Mapping):
            continue
        if (
            _runtime_replan_event_type(
                str(event.get("event") or event.get("event_type") or "").strip()
            )
            != "agent.replan.requested"
        ):
            continue
        payload = event.get("payload")
        if isinstance(payload, Mapping):
            source = str(payload.get("source") or "").strip()
            if source not in _RUNTIME_REPLAN_INGESTION_SOURCES:
                continue
            if (
                source == _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE
                and not _runtime_recovery_continuation_payload_is_trusted(
                    payload,
                    timeline=timeline,
                )
            ):
                continue
            payloads.append(copy_live_replan_payload(payload))
    return payloads


def _runtime_recovery_continuation_replan_payload(
    result: OutcomeLoopResult,
    *,
    timeline: Sequence[Mapping[str, Any]],
    run_id: str,
) -> dict[str, Any]:
    """Build one replan request from an executor-grounded recovery batch."""

    recovery = result.recovery_action_result
    clean_run_id = str(run_id or "").strip()
    source_tool_call_id = str(result.source_tool_call_id or "").strip()
    if (
        not clean_run_id
        or not source_tool_call_id
        or result.disposition is not OutcomeLoopDisposition.CONTINUE_PLAN
        or result.outcome.status is OutcomeStatus.SUCCESS
        or recovery is None
        or recovery.disposition is not RecoveryActionDisposition.CONTINUE_PLAN
        or not recovery.attempts
    ):
        return {}
    source_match = _runtime_recovery_executor_terminal_event(
        timeline,
        run_id=clean_run_id,
        tool_call_id=source_tool_call_id,
        tool_name=result.outcome.tool_name,
    )
    if source_match is None:
        return {}
    source_index, source_event = source_match
    source_result = source_event.get("result")
    if not isinstance(source_result, Mapping) or source_result != result.outcome.raw:
        return {}

    plan = result.recovery_plan
    plan_metadata = (
        plan.metadata
        if plan is not None and isinstance(plan.metadata, Mapping)
        else {}
    )
    source_goal_contract_id = str(
        source_event.get("goal_contract_id") or ""
    ).strip()
    source_goal_criterion_id = str(
        source_event.get("goal_criterion_id") or ""
    ).strip()
    if (
        not source_goal_contract_id
        or not source_goal_criterion_id
        or (
            str(plan_metadata.get("goal_contract_id") or "").strip()
            and str(plan_metadata.get("goal_contract_id") or "").strip()
            != source_goal_contract_id
        )
        or (
            str(plan_metadata.get("goal_criterion_id") or "").strip()
            and str(plan_metadata.get("goal_criterion_id") or "").strip()
            != source_goal_criterion_id
        )
    ):
        # A continuation may refine only the target of the already-bound
        # root criterion.  Recovery-plan metadata is advisory unless it
        # exactly agrees with the executor-owned source receipt.
        return {}
    recovery_action = str(getattr(plan, "action", "") or "").strip()
    recovery_scope_id = str(getattr(plan, "scope_id", "") or "").strip()
    observations: list[dict[str, Any]] = []
    observation_identities: list[tuple[str, str, str]] = []
    seen_observation_call_ids: set[str] = set()
    for batch in recovery.attempts:
        for request in batch.requests:
            if not isinstance(request, Mapping):
                continue
            observation_tool = str(request.get("tool") or "").strip()
            observation_call_id = str(request.get("tool_call_id") or "").strip()
            if (
                not observation_tool
                or not observation_call_id
                or observation_call_id in seen_observation_call_ids
                or str(request.get("source") or "").strip()
                != "runtime_internal_recovery"
                or str(request.get("source_tool_call_id") or "").strip()
                != source_tool_call_id
                or str(request.get("recovery_link_kind") or "").strip()
                != "coordinator_action"
                or (
                    recovery_action
                    and str(request.get("recovery_action") or "").strip()
                    != recovery_action
                )
                or (
                    recovery_scope_id
                    and str(request.get("recovery_scope_id") or "").strip()
                    != recovery_scope_id
                )
            ):
                continue
            batch_result = batch.tool_result_for(observation_call_id)
            if (
                batch_result is None
                or batch_result.event_type != "agent.tool.call"
                or not isinstance(batch_result.result, Mapping)
                or batch_result.result.get("ok") is not True
            ):
                continue
            observation_match = _runtime_recovery_executor_terminal_event(
                timeline,
                run_id=clean_run_id,
                tool_call_id=observation_call_id,
                tool_name=observation_tool,
            )
            if observation_match is None:
                continue
            observation_index, observation_event = observation_match
            if observation_index <= source_index:
                continue
            observed_result = observation_event.get("result")
            if (
                not isinstance(observed_result, Mapping)
                or observed_result != batch_result.result
                or str(observation_event.get("source") or "").strip()
                != "runtime_internal_recovery"
                or str(
                    observation_event.get("source_tool_call_id") or ""
                ).strip()
                != source_tool_call_id
                or str(
                    observation_event.get("recovery_link_kind") or ""
                ).strip()
                != "coordinator_action"
                or (
                    recovery_action
                    and str(
                        observation_event.get("recovery_action") or ""
                    ).strip()
                    != recovery_action
                )
            ):
                continue
            request_input = (
                request.get("input")
                if isinstance(request.get("input"), Mapping)
                else {}
            )
            observed_input = (
                observation_event.get("input_preview")
                if isinstance(observation_event.get("input_preview"), Mapping)
                else {}
            )
            if dict(observed_input) != dict(request_input):
                continue
            snapshot = _runtime_grounded_recovery_observation(
                observation_event,
                source_tool_call_id=source_tool_call_id,
                recovery_action=recovery_action,
            )
            if not snapshot:
                continue
            seen_observation_call_ids.add(observation_call_id)
            observations.append(snapshot)
            observation_identities.append(
                (
                    observation_call_id,
                    observation_tool,
                    str(observation_event.get("request_id") or "").strip(),
                )
            )
    if not observations:
        return {}

    request_id = _runtime_recovery_continuation_request_id(
        run_id=clean_run_id,
        source_tool_call_id=source_tool_call_id,
        recovery_action=recovery_action,
        observation_identities=observation_identities,
    )
    source_provider = _runtime_execution_provider_identity(
        source_result,
        expected_tool=result.outcome.tool_name,
    )
    last_observation = observations[-1]
    metadata = {
        "source_tool_call_id": source_tool_call_id,
        "source_request_id": str(source_event.get("request_id") or "").strip(),
        "source_plan_id": str(source_event.get("plan_id") or "").strip(),
        "source_step_id": str(
            source_event.get("step_id")
            or source_event.get("planner_step_id")
            or ""
        ).strip(),
        "source_provider_kind": str(source_provider.get("provider_kind") or ""),
        "source_provider_id": str(source_provider.get("provider_id") or ""),
        "recovery_action": recovery_action,
        "recovery_scope_id": recovery_scope_id,
        "recovery_observation_tool_call_id": str(
            last_observation.get("source_tool_call_id") or ""
        ),
        "recovery_observation_tool": str(
            last_observation.get("source_tool") or ""
        ),
    }
    payload: dict[str, Any] = {
        "request_id": request_id,
        "trigger": "recovery_observation_ready",
        "status": "requested",
        "source": _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE,
        "run_id": clean_run_id,
        "plan_id": str(source_event.get("plan_id") or "").strip(),
        "source_step_id": str(
            source_event.get("step_id")
            or source_event.get("planner_step_id")
            or ""
        ).strip(),
        "source_tool_name": result.outcome.tool_name,
        "source_tool_call_id": source_tool_call_id,
        "goal_contract_id": source_goal_contract_id,
        "goal_criterion_id": source_goal_criterion_id,
        "source_outcome_status": result.outcome.status.value,
        "source_outcome_reason": result.outcome.reason,
        "target_capability_id": str(
            (plan.required_capabilities[0] if plan and plan.required_capabilities else "")
        ).strip(),
        "condition": "grounded_recovery_observation_available",
        "reason": recovery.reason or "recovery_observation_ready",
        "failure_detail": result.outcome.reason,
        "recovery_action": recovery_action,
        "recovery_scope_id": recovery_scope_id,
        "recovery_observation_tool_call_id": str(
            last_observation.get("source_tool_call_id") or ""
        ),
        "grounded_observation": last_observation,
        "grounded_observations": observations,
        "metadata": {
            key: value for key, value in metadata.items() if value not in (None, "")
        },
    }
    if plan is not None and isinstance(plan.metadata, Mapping):
        for key in (
            "goal_subgoal_id",
            "root_plan_id",
            "root_source_step_id",
        ):
            value = str(plan.metadata.get(key) or "").strip()
            if value:
                payload[key] = value
    compact = {
        key: value
        for key, value in payload.items()
        if value not in (None, "", [], {})
    }
    if not _runtime_recovery_continuation_payload_is_trusted(
        compact,
        timeline=timeline,
    ):
        return {}
    return compact


def _runtime_recovery_continuation_payload_is_trusted(
    payload: Mapping[str, Any],
    *,
    timeline: Sequence[Mapping[str, Any]],
) -> bool:
    """Replay a persisted continuation against both executor-owned calls."""

    if str(payload.get("source") or "").strip() != (
        _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE
    ):
        return False
    run_id = str(payload.get("run_id") or "").strip()
    source_tool_call_id = str(payload.get("source_tool_call_id") or "").strip()
    source_tool = str(payload.get("source_tool_name") or "").strip()
    goal_contract_id = str(payload.get("goal_contract_id") or "").strip()
    goal_criterion_id = str(payload.get("goal_criterion_id") or "").strip()
    recovery_action = str(payload.get("recovery_action") or "").strip()
    recovery_scope_id = str(payload.get("recovery_scope_id") or "").strip()
    metadata = (
        payload.get("metadata")
        if isinstance(payload.get("metadata"), Mapping)
        else {}
    )
    if (
        _string_list(payload.get("fallback_tools"))
        or _mapping_list(payload.get("recovery_actions"))
        or _mapping_list(metadata.get("recovery_actions"))
        or _string_list(payload.get("recommended_tools"))
        or str(payload.get("replan_prompt") or "").strip()
        or payload.get(RUNTIME_PRIVATE_REPLAN_CONTEXT_KEY) is not None
    ):
        # This source reports an already-completed observation and grants no
        # auto-execution authority.  A persisted payload cannot be upgraded
        # into a fallback plan by adding public recovery fields.
        return False
    observations = [
        dict(item)
        for item in _mapping_list(payload.get("grounded_observations"))
    ]
    grounded_observation = payload.get("grounded_observation")
    if (
        not run_id
        or not source_tool_call_id
        or not source_tool
        or not goal_contract_id
        or not goal_criterion_id
        or not recovery_action
        or not recovery_scope_id
        or not observations
        or not isinstance(grounded_observation, Mapping)
        or dict(grounded_observation) != observations[-1]
    ):
        return False
    source_match = _runtime_recovery_executor_terminal_event(
        timeline,
        run_id=run_id,
        tool_call_id=source_tool_call_id,
        tool_name=source_tool,
    )
    if source_match is None:
        return False
    source_index, source_event = source_match
    source_result = source_event.get("result")
    if not isinstance(source_result, Mapping):
        return False
    source_step_id = str(
        source_event.get("step_id")
        or source_event.get("planner_step_id")
        or ""
    ).strip()
    source_plan_id = str(source_event.get("plan_id") or "").strip()
    source_request_id = str(source_event.get("request_id") or "").strip()
    source_provider = _runtime_execution_provider_identity(
        source_result,
        expected_tool=source_tool,
    )
    if (
        str(source_event.get("goal_contract_id") or "").strip()
        != goal_contract_id
        or str(source_event.get("goal_criterion_id") or "").strip()
        != goal_criterion_id
        or not source_step_id
        or not source_plan_id
        or not source_request_id
        or str(payload.get("plan_id") or "").strip() != source_plan_id
        or str(payload.get("source_step_id") or "").strip() != source_step_id
        or str(metadata.get("source_tool_call_id") or "").strip()
        != source_tool_call_id
        or str(metadata.get("source_request_id") or "").strip()
        != source_request_id
        or str(metadata.get("source_plan_id") or "").strip()
        != source_plan_id
        or str(metadata.get("source_step_id") or "").strip()
        != source_step_id
        or str(metadata.get("source_provider_kind") or "").strip()
        != str(source_provider.get("provider_kind") or "").strip()
        or str(metadata.get("source_provider_id") or "").strip()
        != str(source_provider.get("provider_id") or "").strip()
        or str(metadata.get("recovery_action") or "").strip()
        != recovery_action
        or str(metadata.get("recovery_scope_id") or "").strip()
        != recovery_scope_id
    ):
        return False
    normalized_source = from_tool_result(
        source_tool,
        source_result,
        capability_ids_for_tool(source_tool),
    )
    if (
        normalized_source.status is OutcomeStatus.SUCCESS
        or normalized_source.status.value
        != str(payload.get("source_outcome_status") or "").strip()
        or normalized_source.reason
        != str(payload.get("source_outcome_reason") or "").strip()
    ):
        return False

    identities: list[tuple[str, str, str]] = []
    seen_call_ids: set[str] = set()
    for observation in observations:
        observation_call_id = str(
            observation.get("source_tool_call_id") or ""
        ).strip()
        observation_tool = str(observation.get("source_tool") or "").strip()
        if (
            not observation_call_id
            or not observation_tool
            or observation_tool
            not in _RUNTIME_REPLAN_GROUNDING_OBSERVATION_TOOLS
            or observation_call_id in seen_call_ids
            or str(observation.get("recovery_source_tool_call_id") or "").strip()
            != source_tool_call_id
            or str(observation.get("grounded_by") or "").strip()
            != _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE
        ):
            return False
        observation_match = _runtime_recovery_executor_terminal_event(
            timeline,
            run_id=run_id,
            tool_call_id=observation_call_id,
            tool_name=observation_tool,
        )
        if observation_match is None:
            return False
        observation_index, observation_event = observation_match
        if (
            observation_index <= source_index
            or str(observation_event.get("source") or "").strip()
            != "runtime_internal_recovery"
            or str(observation_event.get("source_tool_call_id") or "").strip()
            != source_tool_call_id
            or str(observation_event.get("recovery_link_kind") or "").strip()
            != "coordinator_action"
            or str(observation_event.get("recovery_action") or "").strip()
            != recovery_action
            or str(observation_event.get("recovery_scope_id") or "").strip()
            != recovery_scope_id
            or str(observation_event.get("goal_contract_id") or "").strip()
            != goal_contract_id
            or str(observation_event.get("goal_criterion_id") or "").strip()
            != goal_criterion_id
            or _runtime_grounded_recovery_observation(
                observation_event,
                source_tool_call_id=source_tool_call_id,
                recovery_action=recovery_action,
            )
            != observation
        ):
            return False
        seen_call_ids.add(observation_call_id)
        identities.append(
            (
                observation_call_id,
                observation_tool,
                str(observation_event.get("request_id") or "").strip(),
            )
        )
    expected_request_id = _runtime_recovery_continuation_request_id(
        run_id=run_id,
        source_tool_call_id=source_tool_call_id,
        recovery_action=recovery_action,
        observation_identities=identities,
    )
    return str(payload.get("request_id") or "").strip() == expected_request_id


def _runtime_recovery_executor_terminal_event(
    timeline: Sequence[Mapping[str, Any]],
    *,
    run_id: str,
    tool_call_id: str,
    tool_name: str,
) -> tuple[int, dict[str, Any]] | None:
    """Return the first provider-attested terminal owned by Runtime."""

    expected_run_id = str(run_id or "").strip()
    expected_call_id = str(tool_call_id or "").strip()
    expected_tool = str(tool_name or "").strip()
    if not expected_run_id or not expected_call_id or not expected_tool:
        return None
    for index, raw_event in enumerate(timeline):
        if not isinstance(raw_event, Mapping):
            continue
        nested = (
            raw_event.get("payload")
            if isinstance(raw_event.get("payload"), Mapping)
            else {}
        )
        event = {**dict(nested), **dict(raw_event)}
        event_types = {
            str(source.get(key) or "").strip()
            for source in (raw_event, nested)
            for key in ("event", "event_type")
            if str(source.get(key) or "").strip()
        }
        run_ids = {
            str(source.get("run_id") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("run_id") or "").strip()
        }
        actors = {
            str(source.get("actor") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("actor") or "").strip()
        }
        authorities = {
            str(source.get("execution_authority") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("execution_authority") or "").strip()
        }
        call_ids = {
            str(source.get("tool_call_id") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("tool_call_id") or "").strip()
        }
        request_ids = {
            str(source.get("request_id") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("request_id") or "").strip()
        }
        plan_ids = {
            str(source.get("plan_id") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("plan_id") or "").strip()
        }
        step_ids = {
            str(source.get(key) or "").strip()
            for source in (raw_event, nested)
            for key in ("step_id", "planner_step_id")
            if str(source.get(key) or "").strip()
        }
        tool_names = {
            str(source.get(key) or "").strip()
            for source in (raw_event, nested)
            for key in ("tool", "detail")
            if str(source.get(key) or "").strip()
        }
        goal_contract_ids = {
            str(source.get("goal_contract_id") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("goal_contract_id") or "").strip()
        }
        goal_criterion_ids = {
            str(source.get("goal_criterion_id") or "").strip()
            for source in (raw_event, nested)
            if str(source.get("goal_criterion_id") or "").strip()
        }
        result = event.get("result")
        if (
            len(event_types) != 1
            or not event_types.issubset(
                {"agent.tool.call", "agent.tool.failed", "agent.tool.skipped"}
            )
            or run_ids != {expected_run_id}
            or actors != {"native_runtime"}
            or authorities != {"runtime_tool_executor"}
            or call_ids != {expected_call_id}
            or len(request_ids) > 1
            or len(plan_ids) > 1
            or len(step_ids) > 1
            or tool_names != {expected_tool}
            or len(goal_contract_ids) > 1
            or len(goal_criterion_ids) > 1
            or not isinstance(result, Mapping)
            or not _runtime_execution_provider_identity(
                result,
                expected_tool=expected_tool,
            )
        ):
            continue
        return index, event
    return None


def _runtime_grounded_recovery_observation(
    event: Mapping[str, Any],
    *,
    source_tool_call_id: str,
    recovery_action: str,
) -> dict[str, Any]:
    result = event.get("result")
    if not isinstance(result, Mapping) or result.get("ok") is not True:
        return {}
    tool_name = str(event.get("tool") or event.get("detail") or "").strip()
    input_preview = (
        event.get("input_preview")
        if isinstance(event.get("input_preview"), Mapping)
        else {}
    )
    snapshot = followup_content_snapshot_for_tool_call(
        tool_name,
        dict(result),
        dict(input_preview),
    )
    observation_call_id = str(event.get("tool_call_id") or "").strip()
    if not snapshot or not observation_call_id:
        return {}
    return {
        **snapshot,
        "source_tool_call_id": observation_call_id,
        "recovery_source_tool_call_id": str(source_tool_call_id or "").strip(),
        "recovery_action": str(recovery_action or "").strip(),
        "grounded_by": _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE,
    }


def _runtime_recovery_continuation_request_id(
    *,
    run_id: str,
    source_tool_call_id: str,
    recovery_action: str,
    observation_identities: Sequence[tuple[str, str, str]],
) -> str:
    seed = json.dumps(
        {
            "run_id": str(run_id or "").strip(),
            "source_tool_call_id": str(source_tool_call_id or "").strip(),
            "recovery_action": str(recovery_action or "").strip(),
            "observations": [list(identity) for identity in observation_identities],
        },
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    )
    return (
        "runtime-recovery-continuation-"
        f"{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:24]}"
    )


def _pending_runtime_replan_payloads(
    timeline: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    handled = _handled_runtime_replan_request_identities(timeline)
    payloads: list[dict[str, Any]] = []
    for payload in _timeline_replan_request_payloads(timeline):
        identity = _runtime_replan_payload_identity(payload)
        if identity and identity in handled:
            continue
        payloads.append(payload)
    return payloads


def _pending_auto_replan_recovery_requests_with_task_context(
    replan_payloads: Iterable[Mapping[str, Any]],
    allowed_tools: Iterable[str],
    timeline: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    allowed_tool_list = list(allowed_tools)
    consumed_identities = recovery_action_identities_from_timeline(timeline)
    requests: list[dict[str, Any]] = []
    for payload in replan_payloads:
        if not isinstance(payload, Mapping):
            continue
        raw_start = payload.get("runtime_tool_timeline_start")
        tool_timeline_start = int(raw_start) if isinstance(raw_start, int) else 0
        candidates = _auto_replan_recovery_requests_with_task_context(
            [dict(payload)],
            allowed_tool_list,
            timeline,
            tool_timeline_start=min(
                len(timeline),
                max(0, tool_timeline_start),
            ),
        )
        for request in candidates:
            if recovery_request_repeats_stalled_discovery(
                request,
                timeline,
                tool_timeline_start=min(
                    len(timeline),
                    max(0, tool_timeline_start),
                ),
            ):
                continue
            identity = ensure_recovery_action_identity(request)
            if identity and identity in consumed_identities:
                continue
            requests.append(request)
    return requests


def _runtime_replan_request_action_id(request: Mapping[str, Any]) -> str:
    return str(
        request.get("replan_recovery_action_id")
        or request.get("action_id")
        or ""
    ).strip()


def _runtime_replan_effectful_action_signatures(
    payload: Mapping[str, Any],
) -> tuple[str, ...]:
    metadata = (
        payload.get("metadata")
        if isinstance(payload.get("metadata"), Mapping)
        else {}
    )
    authorized_tools = {
        *_RUNTIME_REPLAN_ACTION_AUTO_SAFE_TOOLS,
        *_string_list(payload.get("fallback_tools")),
    }
    actions = [
        *_mapping_list(metadata.get("recovery_actions")),
        *_mapping_list(payload.get("recovery_actions")),
    ]
    for action in actions:
        tool_name = str(action.get("tool") or action.get("tool_name") or "").strip()
        if tool_name:
            authorized_tools.add(tool_name)
        for deferred in materialized_deferred_items(action):
            deferred_tool = str(
                deferred.get("tool") or deferred.get("tool_name") or ""
            ).strip()
            if deferred_tool:
                authorized_tools.add(deferred_tool)
    try:
        candidates = _auto_replan_recovery_requests(
            [dict(payload)],
            authorized_tools,
        )
    except (TypeError, ValueError):
        return ()
    signatures: list[str] = []
    for request in candidates:
        tool_name = str(request.get("tool") or "").strip()
        if not tool_name or tool_name in READ_ONLY_OBSERVATION_TOOLS:
            continue
        request_input = (
            request.get("input")
            if isinstance(request.get("input"), Mapping)
            else {}
        )
        signature = canonical_replan_action_signature(
            tool_name,
            request_input,
            action_id=_runtime_replan_request_action_id(request),
        )
        if signature and signature not in signatures:
            signatures.append(signature)
    return tuple(signatures)


def _runtime_replan_private_binding_from_payload(
    payload: Mapping[str, Any],
) -> dict[str, str]:
    metadata = (
        payload.get("metadata")
        if isinstance(payload.get("metadata"), Mapping)
        else {}
    )
    binding = {
        "run_id": str(payload.get("run_id") or "").strip(),
        "replan_request_id": str(payload.get("request_id") or "").strip(),
        "source_tool_call_id": str(
            metadata.get("source_tool_call_id") or ""
        ).strip(),
        "source_request_id": str(
            metadata.get("source_request_id") or ""
        ).strip(),
        "source_plan_id": str(metadata.get("source_plan_id") or "").strip(),
        "source_step_id": str(metadata.get("source_step_id") or "").strip(),
        "source_tool": str(payload.get("source_tool_name") or "").strip(),
        "source_provider_kind": str(
            metadata.get("source_provider_kind") or ""
        ).strip(),
        "source_provider_id": str(
            metadata.get("source_provider_id") or ""
        ).strip(),
        "goal_contract_id": str(payload.get("goal_contract_id") or "").strip(),
        "goal_criterion_id": str(payload.get("goal_criterion_id") or "").strip(),
    }
    if (
        str(payload.get("source") or "").strip()
        != "runtime_tool_request_runner"
        or any(not value for value in binding.values())
        or str(payload.get("plan_id") or "").strip()
        != binding["source_plan_id"]
        or str(payload.get("source_step_id") or "").strip()
        != binding["source_step_id"]
    ):
        return {}
    return binding


def _runtime_replan_payload_with_private_authority(
    payload: Mapping[str, Any],
    *,
    timeline: Sequence[Mapping[str, Any]],
    run_id: str,
) -> dict[str, Any]:
    public_payload = dict(payload)
    public_payload.pop(RUNTIME_PRIVATE_REPLAN_CONTEXT_KEY, None)
    binding = _runtime_replan_private_binding_from_payload(public_payload)
    if (
        not binding
        or binding["run_id"] != str(run_id or "").strip()
        or not _runtime_replan_private_source_matches(
            binding,
            timeline=timeline,
        )
    ):
        return public_payload
    context = mint_private_replan_context(
        binding=binding,
        action_signatures=_runtime_replan_effectful_action_signatures(public_payload),
    )
    if context:
        return RuntimeAuthorizedReplanPayload(
            public_payload,
            private_context=context,
        )
    return public_payload


def _runtime_replan_private_source_matches(
    binding: Mapping[str, str],
    *,
    timeline: Sequence[Mapping[str, Any]],
) -> bool:
    matches = 0
    for raw_event in timeline:
        if not isinstance(raw_event, Mapping):
            continue
        raw_payload = (
            raw_event.get("payload")
            if isinstance(raw_event.get("payload"), Mapping)
            else {}
        )
        event = {**dict(raw_payload), **dict(raw_event)}
        event_type = str(
            event.get("event") or event.get("event_type") or ""
        ).strip()
        result = event.get("result")
        if (
            event_type
            not in {"agent.tool.call", "agent.tool.failed", "agent.tool.skipped"}
            or not isinstance(result, Mapping)
            or str(event.get("run_id") or "").strip() != binding["run_id"]
            or str(event.get("tool_call_id") or "").strip()
            != binding["source_tool_call_id"]
            or str(event.get("request_id") or "").strip()
            != binding["source_request_id"]
            or str(event.get("plan_id") or "").strip()
            != binding["source_plan_id"]
            or str(
                event.get("step_id") or event.get("planner_step_id") or ""
            ).strip()
            != binding["source_step_id"]
            or str(event.get("tool") or event.get("detail") or "").strip()
            != binding["source_tool"]
            or str(event.get("goal_contract_id") or "").strip()
            != binding["goal_contract_id"]
            or str(event.get("goal_criterion_id") or "").strip()
            != binding["goal_criterion_id"]
            or not _runtime_owned_terminal_event(
                event,
                result,
                run_id=binding["run_id"],
                plan_id=binding["source_plan_id"],
            )
            or _runtime_execution_provider_identity(result)
            != {
                "provider_kind": binding["source_provider_kind"],
                "provider_id": binding["source_provider_id"],
            }
        ):
            continue
        matches += 1
        if matches > 1:
            return False
    return matches == 1


def _replace_in_memory_runtime_replan_payload(
    timeline: list[dict[str, Any]],
    *,
    dedupe_key: tuple[str, str, str],
    payload: Mapping[str, Any],
) -> None:
    for event in reversed(timeline):
        if not isinstance(event, dict):
            continue
        if _runtime_replan_event_type(
            str(event.get("event") or event.get("event_type") or "").strip()
        ) != "agent.replan.requested":
            continue
        current = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        if _replan_payload_dedupe_key(current) != dedupe_key:
            continue
        event["payload"] = copy_live_replan_payload(payload)
        return


def _bind_trusted_runtime_replan_goal_requests(
    requests: list[dict[str, Any]],
    replan_payloads: Sequence[Mapping[str, Any]],
    *,
    contract: GoalContract | None,
    timeline: Sequence[Mapping[str, Any]],
    run_id: str,
) -> list[dict[str, Any]]:
    """Authorize fallback attempts only from an exact failed Runtime fact.

    Replan events are persisted projections and are not execution authority by
    themselves.  This gate replays their source identity against the immutable
    Goal contract and the provider-attested first terminal event, then mints a
    fresh request identity for one bounded effectful fallback plus its safe
    observation batch.  Stale/public replans remain visible for diagnosis but
    cannot execute a side effect.
    """

    clean_run_id = str(run_id or "").strip()
    if (
        not requests
        or contract is None
        or not clean_run_id
        or contract.run_id != clean_run_id
    ):
        return []
    payload_by_id = {
        str(payload.get("request_id") or "").strip(): payload
        for payload in replan_payloads
        if isinstance(payload, Mapping)
        and str(payload.get("request_id") or "").strip()
    }
    assessment = runtime_goal_assessment(contract, timeline)
    effectful_source_calls: set[str] = set()
    seen_request_signatures: set[tuple[str, str]] = set()
    bound: list[dict[str, Any]] = []
    for request in requests:
        replan_request_id = str(
            request.get("replan_request_id") or ""
        ).strip()
        payload = payload_by_id.get(replan_request_id)
        if payload is None:
            continue
        source = _trusted_runtime_replan_source(
            payload,
            contract=contract,
            assessment=assessment,
            timeline=timeline,
            run_id=clean_run_id,
        )
        if not source:
            continue
        source_call_id = str(source["source_tool_call_id"])
        criterion = contract.criterion(str(source["criterion_id"]))
        tool_name = str(request.get("tool") or "").strip()
        tool_capabilities = set(capability_ids_for_tool(tool_name))
        is_observation = tool_name in READ_ONLY_OBSERVATION_TOOLS
        capability_compatible = bool(
            criterion is not None
            and set(criterion.required_capabilities).issubset(tool_capabilities)
        )
        if criterion is None or not tool_name:
            continue
        source_is_observation_only = (
            str(source.get("source_observation_only") or "").strip() == "true"
        )
        # The exact failed source may authorize several policy-filtered reads
        # needed to decide the next action.  It may never authorize an
        # unrelated write, and only one capability-compatible effectful retry
        # is minted for a source terminal.
        if source_is_observation_only and not is_observation:
            continue
        if not is_observation and (
            not capability_compatible
            or not criterion.required_capabilities
            or str(source.get("source_retryable") or "").strip() != "true"
            or str(source.get("source_step_id") or "").strip()
            not in {*criterion.source_step_ids, *criterion.verifier_step_ids}
            or source_call_id in effectful_source_calls
        ):
            continue
        if not is_observation:
            trusted_signatures = trusted_private_replan_action_signatures(
                payload,
                binding={
                    "run_id": clean_run_id,
                    "replan_request_id": replan_request_id,
                    "source_tool_call_id": source_call_id,
                    "source_request_id": str(source["source_request_id"]),
                    "source_plan_id": str(source["source_plan_id"]),
                    "source_step_id": str(source["source_step_id"]),
                    "source_tool": str(source["source_tool"]),
                    "source_provider_kind": str(source["source_provider_kind"]),
                    "source_provider_id": str(source["source_provider_id"]),
                    "goal_contract_id": contract.contract_id,
                    "goal_criterion_id": criterion.criterion_id,
                },
            )
            request_input = (
                request.get("input")
                if isinstance(request.get("input"), Mapping)
                else {}
            )
            candidate_signature = canonical_replan_action_signature(
                tool_name,
                request_input,
                action_id=_runtime_replan_request_action_id(request),
            )
            if not candidate_signature or candidate_signature not in trusted_signatures:
                continue
        request_signature = _trusted_runtime_replan_request_signature(request)
        if request_signature in seen_request_signatures:
            continue
        item = dict(request)
        ensure_tool_call_id(item)
        # Persisted/model requests do not choose planner authority.  Bind every
        # fallback to the exact Goal step that produced the trusted terminal.
        bound_step_id = str(source["source_step_id"])
        item.update(
            {
                "source": "runtime_planner",
                "planning_reason": "planner_replan_fallback_recovery",
                "plan_id": str(source["source_plan_id"]),
                "step_id": bound_step_id,
                "planner_step_id": bound_step_id,
                "goal_contract_id": contract.contract_id,
                "goal_criterion_id": criterion.criterion_id,
                "root_goal_unchanged": True,
                "replan_source_tool_call_id": source_call_id,
                "replan_source_request_id": str(source["source_request_id"]),
                "replan_source_step_id": str(source["source_step_id"]),
            }
        )
        expected_target = criterion.expected.get("target")
        if is_observation:
            # Observation receipts can guide the loop, but they are not the
            # root action and must not carry synthetic completion evidence.
            item["observation_only"] = True
            item["goal_completion_authority"] = False
            for key in (
                "action_target",
                "postcondition_verified",
                "verification_passed",
                "verified",
                "state",
                "target",
            ):
                item.pop(key, None)
            capability_id = str(item.get("capability_id") or "").strip()
            if capability_id not in tool_capabilities:
                if tool_capabilities:
                    item["capability_id"] = sorted(tool_capabilities)[0]
                else:
                    item.pop("capability_id", None)
        else:
            for key in (
                "postcondition_verified",
                "verification_passed",
                "verified",
                "state",
                "target",
                "goal_completion_authority",
                "observation_only",
            ):
                item.pop(key, None)
            if isinstance(expected_target, Mapping) and expected_target:
                item["action_target"] = dict(expected_target)
            else:
                item.pop("action_target", None)
            effectful_source_calls.add(source_call_id)
        if not str(item.get("request_id") or "").strip():
            digest = hashlib.sha256(
                (
                    f"{replan_request_id}\0{source_call_id}\0"
                    f"{item['tool_call_id']}\0{tool_name}"
                ).encode("utf-8")
            ).hexdigest()[:16]
            item["request_id"] = f"runtime-replan-request-{digest}"
        seen_request_signatures.add(request_signature)
        bound.append(item)
        if len(bound) >= _MODEL_FOLLOWUP_MAX_AUTO_PENDING_REQUESTS:
            break
    return bound


def _trusted_runtime_replan_request_signature(
    request: Mapping[str, Any],
) -> tuple[str, str]:
    tool_name = str(request.get("tool") or "").strip()
    request_input = (
        request.get("input") if isinstance(request.get("input"), Mapping) else {}
    )
    try:
        normalized_input = json.dumps(
            dict(request_input),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
    except (TypeError, ValueError):
        normalized_input = repr(
            sorted(
                dict(request_input).items(),
                key=lambda item: str(item[0]),
            )
        )
    return tool_name, normalized_input


def _trusted_runtime_replan_source(
    payload: Mapping[str, Any],
    *,
    contract: GoalContract,
    assessment: Any,
    timeline: Sequence[Mapping[str, Any]],
    run_id: str,
) -> dict[str, str]:
    metadata = (
        payload.get("metadata")
        if isinstance(payload.get("metadata"), Mapping)
        else {}
    )
    identity = {
        "source_tool_call_id": str(
            metadata.get("source_tool_call_id") or ""
        ).strip(),
        "source_request_id": str(
            metadata.get("source_request_id") or ""
        ).strip(),
        "source_plan_id": str(metadata.get("source_plan_id") or "").strip(),
        "source_step_id": str(metadata.get("source_step_id") or "").strip(),
        "source_tool": str(payload.get("source_tool_name") or "").strip(),
        "source_provider_kind": str(
            metadata.get("source_provider_kind") or ""
        ).strip(),
        "source_provider_id": str(
            metadata.get("source_provider_id") or ""
        ).strip(),
    }
    payload_contract_id = str(payload.get("goal_contract_id") or "").strip()
    payload_criterion_id = str(payload.get("goal_criterion_id") or "").strip()
    payload_source = str(payload.get("source") or "").strip()
    if payload_source == _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE:
        if not _runtime_recovery_continuation_payload_is_trusted(
            payload,
            timeline=timeline,
        ):
            return {}
    elif payload_source != "runtime_tool_request_runner":
        return {}
    if (
        str(payload.get("run_id") or "").strip() != run_id
        or not str(payload.get("request_id") or "").strip()
        or payload_contract_id != contract.contract_id
        or not payload_criterion_id
        or any(not value for value in identity.values())
        or str(payload.get("plan_id") or "").strip()
        != identity["source_plan_id"]
        or str(payload.get("source_step_id") or "").strip()
        != identity["source_step_id"]
    ):
        return {}
    matches: list[
        tuple[Mapping[str, Any], Mapping[str, Any], Any]
    ] = []
    for raw_event in timeline:
        if not isinstance(raw_event, Mapping):
            continue
        raw_payload = (
            raw_event.get("payload")
            if isinstance(raw_event.get("payload"), Mapping)
            else {}
        )
        event = {**dict(raw_payload), **dict(raw_event)}
        event_type = str(
            event.get("event") or event.get("event_type") or ""
        ).strip()
        result = event.get("result")
        if (
            event_type not in {
                "agent.tool.call",
                "agent.tool.failed",
                "agent.tool.skipped",
            }
            or not isinstance(result, Mapping)
            or str(event.get("run_id") or "").strip() != run_id
            or str(event.get("tool_call_id") or "").strip()
            != identity["source_tool_call_id"]
            or str(event.get("request_id") or "").strip()
            != identity["source_request_id"]
            or str(event.get("plan_id") or "").strip()
            != identity["source_plan_id"]
            or str(
                event.get("step_id") or event.get("planner_step_id") or ""
            ).strip()
            != identity["source_step_id"]
            or str(event.get("tool") or event.get("detail") or "").strip()
            != identity["source_tool"]
            or str(event.get("goal_contract_id") or "").strip()
            != payload_contract_id
            or str(event.get("goal_criterion_id") or "").strip()
            != payload_criterion_id
        ):
            continue
        if not _runtime_owned_terminal_event(
            event,
            result,
            run_id=run_id,
            plan_id=identity["source_plan_id"],
        ):
            continue
        provider = _runtime_execution_provider_identity(result)
        if provider != {
            "provider_kind": identity["source_provider_kind"],
            "provider_id": identity["source_provider_id"],
        }:
            continue
        outcome = from_tool_result(
            identity["source_tool"],
            result,
            capabilities=capability_ids_for_tool(identity["source_tool"]),
        )
        if outcome.status not in {
            OutcomeStatus.FAILED,
            OutcomeStatus.PARTIAL,
            OutcomeStatus.SKIPPED,
        }:
            continue
        matches.append((event, result, outcome))
    if len(matches) != 1:
        return {}
    source_event, _source_result, source_outcome = matches[0]
    criterion_ids = {
        evidence.criterion_id
        for evidence in assessment.evidence
        if evidence.kind == "tool_outcome"
        and evidence.source_tool_call_id == identity["source_tool_call_id"]
        and evidence.status in {
            OutcomeStatus.FAILED.value,
            OutcomeStatus.PARTIAL.value,
            OutcomeStatus.SKIPPED.value,
        }
    }
    source_observation_only = bool(
        source_outcome.status is OutcomeStatus.SKIPPED
        or identity["source_tool"] in READ_ONLY_OBSERVATION_TOOLS
    )
    if len(criterion_ids) == 1:
        criterion_id = next(iter(criterion_ids))
        if payload_criterion_id != criterion_id:
            return {}
        return {
            **identity,
            "criterion_id": criterion_id,
            "source_kind": "goal_failure_evidence",
            "source_observation_only": (
                "true" if source_observation_only else "false"
            ),
            "source_retryable": "true" if source_outcome.retryable else "false",
        }
    if criterion_ids or identity["source_tool"] not in READ_ONLY_OBSERVATION_TOOLS:
        return {}
    criterion_id = _goal_bound_runtime_observation_criterion_id(
        contract,
        source_event,
        payload,
    )
    if not criterion_id:
        return {}
    return {
        **identity,
        "criterion_id": criterion_id,
        "source_kind": "goal_bound_observation_failure",
        "source_observation_only": "true",
        "source_retryable": "true" if source_outcome.retryable else "false",
    }


def _goal_bound_runtime_observation_criterion_id(
    contract: GoalContract,
    event: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> str:
    if str(event.get("source") or "").strip() != "runtime_planner":
        return ""
    step_id = str(
        event.get("step_id") or event.get("planner_step_id") or ""
    ).strip()
    capability_id = str(event.get("capability_id") or "").strip()
    payload_contract_id = str(payload.get("goal_contract_id") or "").strip()
    payload_criterion_id = str(payload.get("goal_criterion_id") or "").strip()
    event_contract_id = str(event.get("goal_contract_id") or "").strip()
    event_criterion_id = str(event.get("goal_criterion_id") or "").strip()
    if (
        payload_contract_id != contract.contract_id
        or event_contract_id != contract.contract_id
        or not payload_criterion_id
        or event_criterion_id != payload_criterion_id
    ):
        return ""
    candidates = [
        criterion
        for criterion in contract.criteria
        if step_id in {*criterion.source_step_ids, *criterion.verifier_step_ids}
        and set(criterion.required_capabilities).issubset({capability_id})
    ]
    if len(candidates) != 1:
        return ""
    criterion_id = candidates[0].criterion_id
    if payload_criterion_id != criterion_id or event_criterion_id != criterion_id:
        return ""
    return criterion_id


def _handled_runtime_replan_request_identities(
    timeline: list[dict[str, Any]],
) -> set[str]:
    handled: set[str] = set()
    for event in timeline:
        if not isinstance(event, Mapping):
            continue
        event_type = str(event.get("event") or event.get("event_type") or "").strip()
        base_event_type = _runtime_progress_base_event_type(event_type)
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        if base_event_type == "agent.recovery.planned" and str(
            event.get("recovery_owner") or payload.get("recovery_owner") or ""
        ).strip() == "coordinator":
            identity = str(
                event.get("replan_request_id")
                or payload.get("replan_request_id")
                or ""
            ).strip()
            if identity:
                handled.add(identity)
            continue
        if base_event_type != "agent.replan.recovery.updated":
            continue
        if recovery_action_identities_from_timeline([event]):
            continue
        identity = str(
            event.get("request_id")
            or payload.get("request_id")
            or event.get("replan_request_id")
            or payload.get("replan_request_id")
            or ""
        ).strip()
        if identity:
            handled.add(identity)
    return handled


def _timeline_has_replan_followup_context(
    timeline: list[dict[str, Any]],
    replan_payloads: list[dict[str, Any]],
) -> bool:
    target = {
        identity
        for identity in (
            _runtime_replan_payload_identity(payload)
            for payload in replan_payloads
            if isinstance(payload, Mapping)
        )
        if identity
    }
    if not target:
        return False
    for event in timeline:
        if not isinstance(event, Mapping):
            continue
        if str(event.get("event") or "").strip() != "agent.model.followup_context":
            continue
        event_payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        requests = event.get("replan_requests")
        if not isinstance(requests, list):
            requests = event_payload.get("replan_requests")
        if not isinstance(requests, list):
            continue
        existing = {
            identity
            for identity in (
                _runtime_replan_payload_identity(request)
                for request in requests
                if isinstance(request, Mapping)
            )
            if identity
        }
        if target.issubset(existing):
            return True
    return False


def _runtime_replan_payload_identity(payload: Mapping[str, Any]) -> str:
    request_id = str(payload.get("request_id") or "").strip()
    if request_id:
        return request_id
    dedupe_key = _replan_payload_dedupe_key(payload)
    if not dedupe_key:
        return ""
    return "|".join(dedupe_key)


def _replan_payload_dedupe_key(payload: Mapping[str, Any]) -> tuple[str, str, str] | None:
    step_id = str(
        payload.get("source_step_id") or payload.get("planner_step_id") or ""
    ).strip()
    tool_name = str(
        payload.get("source_tool_name") or payload.get("tool_name") or ""
    ).strip()
    trigger = str(payload.get("trigger") or payload.get("replan_trigger") or "").strip()
    if not step_id and not tool_name:
        return None
    return (step_id, tool_name, trigger)


def _runtime_replan_planning_reason(triggers: list[str]) -> str:
    clean = {str(trigger or "").strip() for trigger in triggers if str(trigger or "").strip()}
    if clean == {"verification_failed"}:
        return "planner_replan_after_verification_failed"
    if clean == {"tool_unavailable"}:
        return "planner_replan_after_tool_unavailable"
    if "verification_failed" in clean:
        return "planner_replan_after_mixed_runtime_failure"
    return "planner_replan_after_tool_failure"


def _runtime_replan_capability_recovery(
    requests: list[dict[str, Any]],
    *,
    allowed_tools: Iterable[str],
) -> list[dict[str, Any]]:
    capability_ids = _ordered_text_list(
        [
            str(request.get("target_capability_id") or "").strip()
            for request in requests
            if str(request.get("trigger") or "").strip() == "tool_unavailable"
            and str(request.get("target_capability_id") or "").strip()
        ]
    )
    if not capability_ids:
        return []
    snapshots = {
        str(snapshot.capability_id or "").strip(): snapshot
        for snapshot in capability_snapshots(
            allowed_tools=allowed_tools,
            capability_ids=capability_ids,
        )
    }
    recoveries: dict[str, dict[str, Any]] = {}
    for request in requests:
        if str(request.get("trigger") or "").strip() != "tool_unavailable":
            continue
        capability_id = str(request.get("target_capability_id") or "").strip()
        if not capability_id:
            continue
        snapshot = snapshots.get(capability_id)
        recovery = recoveries.setdefault(
            capability_id,
            {
                "capability_id": capability_id,
                "title": str(getattr(snapshot, "title", "") or "").strip(),
                "category": str(getattr(snapshot, "category", "") or "").strip(),
                "description": str(getattr(snapshot, "description", "") or "").strip(),
                "risk_level": str(getattr(snapshot, "risk_level", "") or "").strip(),
                "approval_required": bool(getattr(snapshot, "approval_required", False)),
                "tools": list(getattr(snapshot, "tools", []) or []),
                "available_tools": list(getattr(snapshot, "available_tools", []) or []),
                "missing_tools": list(getattr(snapshot, "missing_tools", []) or []),
                "fallback_tools": [],
                "source_step_ids": [],
                "missing_permissions": [],
                "blocking_conditions": [],
            },
        )
        step_id = str(request.get("source_step_id") or "").strip()
        if step_id and step_id not in recovery["source_step_ids"]:
            recovery["source_step_ids"].append(step_id)
        for key in ("fallback_tools",):
            recovery[key] = _ordered_text_list(
                [*recovery.get(key, []), *_string_list(request.get(key))]
            )
        metadata = request.get("metadata") if isinstance(request.get("metadata"), Mapping) else {}
        for key in ("missing_permissions", "blocking_conditions"):
            recovery[key] = _ordered_text_list(
                [*recovery.get(key, []), *_string_list(metadata.get(key))]
            )
    result: list[dict[str, Any]] = []
    for capability_id in capability_ids:
        recovery = recoveries.get(capability_id)
        if not recovery:
            continue
        missing_tools = _string_list(recovery.get("missing_tools"))
        missing_permissions = _string_list(recovery.get("missing_permissions"))
        blocking_conditions = _string_list(recovery.get("blocking_conditions"))
        if missing_permissions:
            suggested_action = "resolve_permissions"
        elif blocking_conditions:
            suggested_action = "clear_runtime_blockers"
        elif missing_tools:
            suggested_action = "enable_tools"
        else:
            suggested_action = "inspect_capability"
        recovery["suggested_action"] = suggested_action
        recovery["recommended_enable_tools"] = missing_tools[:6]
        result.append(
            {key: value for key, value in recovery.items() if value not in ("", [], {})}
        )
    return result


def _runtime_replan_recovery_actions(
    requests: Iterable[Mapping[str, Any]],
    *,
    allowed_tools: Iterable[str],
) -> list[dict[str, Any]]:
    allowed = {str(tool or "").strip() for tool in allowed_tools if str(tool or "").strip()}
    actions: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for request in requests:
        if not isinstance(request, Mapping):
            continue
        for action in _mapping_list(request.get("recovery_actions")):
            tool_name = str(action.get("tool") or "").strip()
            if allowed and tool_name not in allowed:
                continue
            action_input = (
                action.get("input")
                if isinstance(action.get("input"), Mapping)
                else {}
            )
            signature = (tool_name, repr(sorted(dict(action_input).items())))
            if not tool_name or signature in seen:
                continue
            seen.add(signature)
            actions.append(dict(action))
    return actions


def _runtime_replan_recovery_targets(
    requests: Iterable[Mapping[str, Any]],
) -> list[dict[str, str]]:
    targets: list[dict[str, str]] = []
    seen: set[tuple[str, str, str]] = set()
    for request in requests:
        if not isinstance(request, Mapping):
            continue
        target = {
            key: str(request.get(key) or "").strip()
            for key in ("target_app_name", "target_app_query", "target_search_text")
        }
        signature = (
            target["target_app_name"],
            target["target_app_query"],
            target["target_search_text"],
        )
        if not any(signature) or signature in seen:
            continue
        seen.add(signature)
        targets.append({key: value for key, value in target.items() if value})
    return targets


def _runtime_replan_recovery_observations(
    requests: Iterable[Mapping[str, Any]],
    timeline: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    request_list = [request for request in requests if isinstance(request, Mapping)]
    request_ids = {
        str(request.get("request_id") or "").strip()
        for request in request_list
        if str(request.get("request_id") or "").strip()
    }
    observations: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for request in request_list:
        if str(request.get("source") or "").strip() != (
            _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE
        ):
            continue
        embedded = _mapping_list(request.get("grounded_observations"))
        if not embedded and isinstance(request.get("grounded_observation"), Mapping):
            embedded = [dict(request["grounded_observation"])]
        for observation in embedded:
            if str(observation.get("grounded_by") or "").strip() != (
                _RUNTIME_RECOVERY_CONTINUATION_REPLAN_SOURCE
            ):
                continue
            signature = (
                str(observation.get("source_tool") or "").strip(),
                str(observation.get("source_tool_call_id") or "").strip(),
                str(
                    observation.get("text")
                    or observation.get("summary")
                    or observation.get("path")
                    or ""
                ).strip(),
            )
            if not all(signature[:2]) or signature in seen:
                continue
            seen.add(signature)
            observations.append(dict(observation))
    if not request_ids or not timeline:
        return observations[-6:]
    for event in timeline:
        if not _runtime_replan_recovery_tool_event(event, request_ids):
            continue
        tool_name = str(event.get("detail") or event.get("tool") or "").strip()
        result = event.get("result") if isinstance(event.get("result"), dict) else {}
        input_preview = (
            event.get("input_preview")
            if isinstance(event.get("input_preview"), dict)
            else {}
        )
        snapshot = followup_content_snapshot_for_tool_call(
            tool_name,
            result,
            input_preview,
        )
        if not snapshot:
            continue
        _attach_replan_observation_trace(snapshot, event)
        signature = (
            str(snapshot.get("source_tool") or "").strip(),
            str(snapshot.get("replan_request_id") or "").strip(),
            str(snapshot.get("text") or snapshot.get("summary") or snapshot.get("path") or "").strip(),
        )
        if signature in seen:
            continue
        seen.add(signature)
        observations.append(snapshot)
    return observations[-6:]


def _runtime_replan_recovery_tool_event(
    event: Mapping[str, Any],
    request_ids: set[str],
) -> bool:
    if not isinstance(event, Mapping):
        return False
    if str(event.get("event") or "").strip() != "agent.tool.call":
        return False
    replan_request_id = str(event.get("replan_request_id") or "").strip()
    if replan_request_id:
        return replan_request_id in request_ids
    return str(event.get("planning_reason") or "").strip() == (
        "planner_verification_recovery_observation"
    )


def _attach_replan_observation_trace(
    snapshot: dict[str, Any],
    event: Mapping[str, Any],
) -> None:
    for key in (
        "replan_request_id",
        "replan_trigger",
        "target_app_name",
        "target_app_query",
        "target_search_text",
        "materialized_from_request_id",
        "materialization_source_request_id",
        "materialization_source_step_id",
        "materialization_binding_id",
        "materialized_content_sha256",
        "materialization_authority",
        "goal_contract_id",
        "goal_criterion_id",
        "runtime_stage",
        "runtime_role",
    ):
        value = str(event.get(key) or "").strip()
        if value:
            snapshot[key] = value
    for key in ("replan_triggers", "replan_signal_ids"):
        values = _string_list(event.get(key))
        if values:
            snapshot[key] = values


def _model_replan_followup_context_message(payload: dict[str, Any]) -> str:
    requests = [
        request
        for request in payload.get("replan_requests", [])
        if isinstance(request, dict)
    ]
    fallback_tools = _string_list(payload.get("fallback_tools"))
    failed_tools = _string_list(payload.get("failed_tools"))
    planning_reason = str(payload.get("planning_reason") or "").strip()
    lines = _runtime_replan_message_preamble(planning_reason)
    followup_target = (
        payload.get("followup_target")
        if isinstance(payload.get("followup_target"), Mapping)
        else {}
    )
    target_instruction = _model_followup_target_instruction(followup_target)
    if target_instruction:
        lines.append(target_instruction.strip())
    pending_plan_instruction = _model_followup_pending_plan_instruction(payload)
    if pending_plan_instruction:
        lines.append(pending_plan_instruction)
    if failed_tools:
        lines.append(f"Failed tools: {', '.join(failed_tools)}.")
    if fallback_tools:
        lines.append(f"Preferred fallback tools: {', '.join(fallback_tools)}.")
    recovery_actions = [
        item
        for item in payload.get("recovery_actions", [])
        if isinstance(item, dict)
    ]
    if recovery_actions:
        lines.append("Runtime recovery actions:")
        for item in recovery_actions[:5]:
            tool_name = str(item.get("tool") or "").strip()
            label = str(item.get("label") or tool_name).strip()
            action_input = (
                item.get("input")
                if isinstance(item.get("input"), dict)
                else {}
            )
            parts = [part for part in (label, tool_name) if part]
            if action_input:
                parts.append(f"input={_model_followup_input_preview_text(action_input)}")
            if parts:
                lines.append(f"- {'; '.join(parts)}")
    recovery_targets = [
        item
        for item in payload.get("recovery_targets", [])
        if isinstance(item, dict)
    ]
    if recovery_targets:
        lines.append("Recovery targets:")
        for item in recovery_targets[:3]:
            parts = [
                part
                for part in (
                    _runtime_replan_target_part("app", item.get("target_app_name")),
                    _runtime_replan_target_part("query", item.get("target_app_query")),
                    _runtime_replan_target_part("text", item.get("target_search_text")),
                )
                if part
            ]
            if parts:
                lines.append(f"- {'; '.join(parts)}")
    snapshot_text = _followup_content_snapshots_message(payload)
    if snapshot_text:
        lines.append(snapshot_text.strip())
    capability_recovery = [
        item
        for item in payload.get("capability_recovery", [])
        if isinstance(item, dict)
    ]
    if capability_recovery:
        lines.append("Capability recovery:")
        for item in capability_recovery[:5]:
            capability_id = str(item.get("capability_id") or "").strip()
            missing_tools = _string_list(item.get("missing_tools"))
            available_tools = _string_list(item.get("available_tools"))
            missing_permissions = _string_list(item.get("missing_permissions"))
            blocking_conditions = _string_list(item.get("blocking_conditions"))
            parts = [capability_id] if capability_id else []
            if missing_tools:
                parts.append(f"enable_tools={', '.join(missing_tools[:6])}")
            if available_tools:
                parts.append(f"available_tools={', '.join(available_tools[:6])}")
            if missing_permissions:
                parts.append(f"permissions={', '.join(missing_permissions[:6])}")
            if blocking_conditions:
                parts.append(f"blockers={', '.join(blocking_conditions[:6])}")
            if parts:
                lines.append(f"- {'; '.join(parts)}")
    task_progress = (
        payload.get("task_progress")
        if isinstance(payload.get("task_progress"), dict)
        else {}
    )
    if task_progress:
        lines.append("Task progress:")
        for key, label in (
            ("completed_steps", "completed_steps"),
            ("blocked_steps", "blocked_steps"),
            ("pending_steps", "pending_steps"),
            ("waiting_approval_steps", "waiting_approval_steps"),
        ):
            values = _string_list(task_progress.get(key))
            if values:
                lines.append(f"- {label}: {', '.join(values)}")
        workspace_items = [
            item
            for item in task_progress.get("workspace_items", [])
            if isinstance(item, dict)
        ]
        if workspace_items:
            rendered_items = []
            for item in workspace_items[:8]:
                kind = str(item.get("kind") or "").strip()
                path = str(item.get("path") or item.get("title") or "").strip()
                if path:
                    rendered_items.append(f"{kind}:{path}" if kind else path)
            if rendered_items:
                lines.append(f"- workspace_items: {', '.join(rendered_items)}")
    task_core = payload.get("task_core") if isinstance(payload.get("task_core"), dict) else {}
    if task_core:
        lines.extend(_runtime_replan_task_core_message_lines(task_core))
    for index, request in enumerate(requests[:3], start=1):
        detail = str(request.get("failure_detail") or "").strip()
        reason = str(request.get("reason") or "").strip()
        prompt = str(request.get("replan_prompt") or "").strip()
        lines.append(f"Replan request {index}:")
        if request.get("request_id"):
            lines.append(f"- request_id: {request['request_id']}")
        if request.get("source_step_id"):
            lines.append(f"- failed_step: {request['source_step_id']}")
        if request.get("source_tool_name"):
            lines.append(f"- failed_tool: {request['source_tool_name']}")
        if request.get("target_capability_id"):
            lines.append(f"- target_capability: {request['target_capability_id']}")
        if detail:
            lines.append(f"- failure_detail: {detail}")
        if reason:
            lines.append(f"- replan_reason: {reason}")
        if prompt:
            lines.append(f"- planner_replan_prompt: {prompt}")
    return "\n".join(lines)


def _runtime_replan_target_part(label: str, value: Any) -> str:
    clean = str(value or "").strip()
    return f"{label}={clean}" if clean else ""


def _runtime_replan_task_core_message_lines(task_core: Mapping[str, Any]) -> list[str]:
    lines = ["Task workspace:"]
    workspace = (
        task_core.get("workspace")
        if isinstance(task_core.get("workspace"), Mapping)
        else {}
    )
    workspace_title = str(
        workspace.get("title") or workspace.get("workspace_id") or ""
    ).strip()
    if workspace_title:
        lines.append(f"- workspace: {workspace_title}")
    workspace_items = [
        item
        for item in workspace.get("items", [])
        if isinstance(item, Mapping)
    ]
    if workspace_items:
        rendered = []
        for item in workspace_items[:8]:
            kind = str(item.get("kind") or "").strip()
            status = str(item.get("status") or "planned").strip()
            path = str(item.get("path") or item.get("title") or "").strip()
            source_step_id = str(item.get("source_step_id") or "").strip()
            metadata = item.get("metadata") if isinstance(item.get("metadata"), Mapping) else {}
            pattern = str(metadata.get("pattern") or "").strip()
            parts = [part for part in (kind, status, path, source_step_id, pattern) if part]
            if parts:
                rendered.append(" · ".join(parts))
        if rendered:
            lines.append(f"- workspace_items: {'; '.join(rendered)}")
    todos = [todo for todo in task_core.get("todos", []) if isinstance(todo, Mapping)]
    if todos:
        rendered = []
        for todo in todos[:8]:
            step_id = str(todo.get("step_id") or todo.get("todo_id") or "").strip()
            status = str(todo.get("status") or "planned").strip()
            tool = str(todo.get("tool_name") or "").strip()
            parts = [part for part in (step_id, status, tool) if part]
            if parts:
                rendered.append(" · ".join(parts))
        if rendered:
            lines.append(f"- todos: {'; '.join(rendered)}")
    checkpoints = [
        checkpoint
        for checkpoint in task_core.get("checkpoints", [])
        if isinstance(checkpoint, Mapping)
    ]
    if checkpoints:
        rendered = []
        for checkpoint in checkpoints[:5]:
            step_id = str(
                checkpoint.get("after_step_id") or checkpoint.get("step_id") or ""
            ).strip()
            status = str(checkpoint.get("status") or "planned").strip()
            title = str(checkpoint.get("title") or checkpoint.get("checkpoint_id") or "").strip()
            parts = [part for part in (step_id, status, title) if part]
            if parts:
                rendered.append(" · ".join(parts))
        if rendered:
            lines.append(f"- checkpoints: {'; '.join(rendered)}")
    return lines


def _runtime_replan_message_preamble(planning_reason: str) -> list[str]:
    if planning_reason == "planner_replan_after_verification_failed":
        return [
            (
                "Runtime replan context: post-action verification did not confirm "
                "the requested desktop state."
            ),
            (
                "Continue the existing task workspace. Do not ask the user to perform "
                "the desktop-capable action manually."
            ),
            (
                "Rediscover or inspect the visible app/window state, choose the next "
                "safe observable action, and keep all approval and policy gates."
            ),
        ]
    if planning_reason == "planner_replan_after_tool_unavailable":
        return [
            "Runtime replan context: a planned tool is unavailable.",
            (
                "Continue the existing task workspace. Select another available "
                "capability or ask only for the missing permission/tool."
            ),
            "Keep all approval and policy gates.",
        ]
    return [
        "Runtime replan context: a planned tool failed or could not be verified.",
        (
            "Continue the existing task workspace. Do not ask the user to perform the "
            "tool-capable action manually."
        ),
        (
            "Inspect the failure, choose the next safe observable action, and keep all "
            "approval and policy gates."
        ),
    ]


def _runtime_replan_task_progress_summary(
    replan_payloads: list[dict[str, Any]],
    timeline: list[dict[str, Any]],
) -> dict[str, Any]:
    if not timeline:
        return {}
    core_ids = {
        str(payload.get("core_id") or "").strip()
        for payload in replan_payloads
        if isinstance(payload, Mapping) and str(payload.get("core_id") or "").strip()
    }
    plan_ids = {
        str(payload.get("plan_id") or "").strip()
        for payload in replan_payloads
        if isinstance(payload, Mapping) and str(payload.get("plan_id") or "").strip()
    }
    todos_by_step: dict[str, dict[str, Any]] = {}
    checkpoints_by_step: dict[str, dict[str, Any]] = {}
    workspace_items_by_id: dict[str, dict[str, Any]] = {}
    for payload in replan_payloads:
        if not isinstance(payload, Mapping):
            continue
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), Mapping) else {}
        task_context = (
            metadata.get("task_core_context")
            if isinstance(metadata.get("task_core_context"), Mapping)
            else {}
        )
        if not task_context:
            continue
        workspace_items_by_id.update(
            {
                _runtime_workspace_item_key(item): item
                for item in _runtime_workspace_item_summaries(
                    task_context.get("workspace_items")
                )
                if _runtime_workspace_item_key(item)
            }
        )
        for todo in task_context.get("todos", []):
            if not isinstance(todo, Mapping):
                continue
            step_id = str(todo.get("step_id") or "").strip()
            if not step_id:
                continue
            todos_by_step[step_id] = {
                "step_id": step_id,
                "title": str(todo.get("title") or step_id).strip(),
                "status": str(todo.get("status") or "").strip(),
                "tool": str(todo.get("tool_name") or "").strip(),
                "approval_required": bool(todo.get("approval_required")),
            }
        for checkpoint in task_context.get("checkpoints", []):
            if not isinstance(checkpoint, Mapping):
                continue
            step_id = str(
                checkpoint.get("after_step_id") or checkpoint.get("step_id") or ""
            ).strip()
            if not step_id:
                continue
            checkpoints_by_step[step_id] = {
                "step_id": step_id,
                "title": str(checkpoint.get("title") or step_id).strip(),
                "status": str(checkpoint.get("status") or "").strip(),
                "checkpoint_id": str(checkpoint.get("checkpoint_id") or "").strip(),
            }
    for event in timeline:
        if not isinstance(event, Mapping):
            continue
        event_name = str(event.get("event") or "").strip()
        base_event_name = _runtime_progress_base_event_type(event_name)
        event_payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        core_id = str(event.get("core_id") or event_payload.get("core_id") or "").strip()
        plan_id = str(event.get("plan_id") or event_payload.get("plan_id") or "").strip()
        if core_ids and core_id and core_id not in core_ids:
            continue
        if plan_ids and plan_id and plan_id not in plan_ids:
            continue
        if _runtime_planner_base_event_type(event_name) == "agent.task_core.created":
            task_core = (
                event_payload.get("task_core")
                if isinstance(event_payload.get("task_core"), Mapping)
                else {}
            )
            workspace = (
                task_core.get("workspace")
                if isinstance(task_core.get("workspace"), Mapping)
                else {}
            )
            workspace_items_by_id = {
                _runtime_workspace_item_key(item): item
                for item in _runtime_workspace_item_summaries(workspace.get("items"))
                if _runtime_workspace_item_key(item)
            }
            continue
        if base_event_name == "agent.task.workspace_item.updated":
            item = (
                event.get("workspace_item")
                if isinstance(event.get("workspace_item"), Mapping)
                else {}
            )
            summaries = _runtime_workspace_item_summaries([item])
            if summaries:
                summary = {
                    **summaries[0],
                    "status": str(
                        event.get("status") or summaries[0].get("status") or ""
                    ).strip(),
                }
                key = _runtime_workspace_item_key(summary)
                if key:
                    workspace_items_by_id[key] = summary
            continue
        if base_event_name == "agent.task.todo.updated":
            step_id = str(event.get("step_id") or "").strip()
            if not step_id:
                continue
            todo = event.get("todo") if isinstance(event.get("todo"), Mapping) else {}
            todos_by_step[step_id] = {
                "step_id": step_id,
                "title": str(todo.get("title") or event.get("detail") or step_id).strip(),
                "status": str(event.get("status") or todo.get("status") or "").strip(),
                "tool": str(event.get("tool") or todo.get("tool_name") or "").strip(),
                "approval_required": bool(todo.get("approval_required")),
            }
            continue
        if base_event_name == "agent.task.checkpoint.updated":
            step_id = str(event.get("step_id") or "").strip()
            if not step_id:
                continue
            checkpoint = (
                event.get("checkpoint")
                if isinstance(event.get("checkpoint"), Mapping)
                else {}
            )
            checkpoints_by_step[step_id] = {
                "step_id": step_id,
                "title": str(checkpoint.get("title") or event.get("detail") or step_id).strip(),
                "status": str(event.get("status") or checkpoint.get("status") or "").strip(),
                "checkpoint_id": str(
                    event.get("checkpoint_id") or checkpoint.get("checkpoint_id") or ""
                ).strip(),
            }

    todos = list(todos_by_step.values())
    checkpoints = list(checkpoints_by_step.values())
    workspace_items = list(workspace_items_by_id.values())
    if not todos and not checkpoints and not workspace_items:
        return {}
    summary: dict[str, Any] = {
        "todo_count": len(todos),
        "checkpoint_count": len(checkpoints),
        "todos": todos[:20],
        "checkpoints": checkpoints[:20],
    }
    for status, key in (
        ("completed", "completed_steps"),
        ("blocked", "blocked_steps"),
        ("pending", "pending_steps"),
        ("waiting_approval", "waiting_approval_steps"),
        ("skipped", "skipped_steps"),
    ):
        values = [
            str(todo.get("step_id") or "").strip()
            for todo in todos
            if str(todo.get("status") or "").strip() == status
            and str(todo.get("step_id") or "").strip()
        ]
        if values:
            summary[key] = values
    if workspace_items:
        summary["workspace_items"] = workspace_items
    return summary


def _runtime_replan_task_core_payload(
    replan_payloads: list[dict[str, Any]],
    timeline: list[dict[str, Any]],
) -> dict[str, Any]:
    if not timeline:
        return {}
    core_ids = {
        str(payload.get("core_id") or "").strip()
        for payload in replan_payloads
        if isinstance(payload, Mapping) and str(payload.get("core_id") or "").strip()
    }
    plan_ids = {
        str(payload.get("plan_id") or "").strip()
        for payload in replan_payloads
        if isinstance(payload, Mapping) and str(payload.get("plan_id") or "").strip()
    }
    task_core_event = _runtime_replan_latest_task_core_event(
        timeline,
        core_ids=core_ids,
        plan_ids=plan_ids,
    )
    if not task_core_event:
        return {}
    event_payload = (
        task_core_event.get("payload")
        if isinstance(task_core_event.get("payload"), Mapping)
        else {}
    )
    task_core = (
        event_payload.get("task_core")
        if isinstance(event_payload.get("task_core"), Mapping)
        else {}
    )
    if not task_core:
        return {}
    replay_events = _runtime_replan_task_core_replay_events(
        timeline,
        core_ids=core_ids,
        plan_ids=plan_ids,
    )
    replayed = _runtime_replan_replayed_task_core_payload(
        task_core,
        replay_events,
    )
    if replayed:
        return replayed
    return dict(task_core)


def _runtime_replan_latest_task_core_event(
    timeline: list[dict[str, Any]],
    *,
    core_ids: set[str],
    plan_ids: set[str],
) -> Mapping[str, Any]:
    for event in reversed(timeline):
        if not isinstance(event, Mapping):
            continue
        event_name = str(event.get("event") or "").strip()
        if not event_name.endswith(".task_core.created"):
            continue
        if not _runtime_replan_event_matches_ids(event, core_ids, plan_ids):
            continue
        return event
    return {}


def _runtime_replan_task_core_replay_events(
    timeline: list[dict[str, Any]],
    *,
    core_ids: set[str],
    plan_ids: set[str],
) -> list[Mapping[str, Any]]:
    events: list[Mapping[str, Any]] = []
    for event in timeline:
        if not isinstance(event, Mapping):
            continue
        event_name = str(event.get("event") or "").strip()
        if not (
            event_name.endswith(".task_core.created")
            or event_name.endswith(".task.workspace_item.updated")
            or event_name.endswith(".task.todo.updated")
            or event_name.endswith(".task.checkpoint.updated")
        ):
            continue
        if not _runtime_replan_event_matches_ids(event, core_ids, plan_ids):
            continue
        events.append(event)
    return events


def _runtime_replan_event_matches_ids(
    event: Mapping[str, Any],
    core_ids: set[str],
    plan_ids: set[str],
) -> bool:
    event_payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
    core_id = str(event.get("core_id") or event_payload.get("core_id") or "").strip()
    plan_id = str(event.get("plan_id") or event_payload.get("plan_id") or "").strip()
    if core_ids:
        return bool(core_id and core_id in core_ids)
    if plan_ids:
        return bool(plan_id and plan_id in plan_ids)
    return True


def _runtime_replan_replayed_task_core_payload(
    task_core: Mapping[str, Any],
    replay_events: list[Mapping[str, Any]],
) -> dict[str, Any]:
    try:
        from apps.shell.yachiyo_agent.events import (
            public_run_event_from_payload,
            run_event_parent_context,
        )
        from apps.shell.yachiyo_agent.task_core_snapshots import (
            task_core_snapshot_from_payload,
        )
    except Exception:
        return {}
    normalized_task_core = _runtime_replan_normalized_task_core_payload(task_core)
    context = run_event_parent_context({"task_core": normalized_task_core})
    public_events = [
        public_run_event_from_payload(event, sequence=index + 1, context=context)
        for index, event in enumerate(replay_events)
    ]
    snapshot = task_core_snapshot_from_payload(
        {"task_core": normalized_task_core},
        events=public_events,
    )
    if snapshot is None:
        return {}
    return snapshot.model_dump(mode="json")


def _runtime_replan_normalized_task_core_payload(
    task_core: Mapping[str, Any],
) -> dict[str, Any]:
    normalized = dict(task_core)
    workspace = (
        dict(normalized.get("workspace"))
        if isinstance(normalized.get("workspace"), Mapping)
        else {}
    )
    if workspace:
        workspace.setdefault(
            "title",
            str(workspace.get("workspace_id") or "Task Workspace").strip(),
        )
        workspace["items"] = [
            _runtime_replan_normalized_workspace_item(item)
            for item in workspace.get("items", [])
            if isinstance(item, Mapping)
        ]
        normalized["workspace"] = workspace
    normalized["todos"] = [
        _runtime_replan_normalized_todo_item(todo)
        for todo in normalized.get("todos", [])
        if isinstance(todo, Mapping)
    ]
    normalized["checkpoints"] = [
        _runtime_replan_normalized_checkpoint(checkpoint)
        for checkpoint in normalized.get("checkpoints", [])
        if isinstance(checkpoint, Mapping)
    ]
    return normalized


def _runtime_replan_normalized_workspace_item(item: Mapping[str, Any]) -> dict[str, Any]:
    normalized = dict(item)
    title = str(
        normalized.get("title")
        or normalized.get("path")
        or normalized.get("item_id")
        or "workspace item"
    ).strip()
    normalized["title"] = title
    return normalized


def _runtime_replan_normalized_todo_item(todo: Mapping[str, Any]) -> dict[str, Any]:
    normalized = dict(todo)
    title = str(
        normalized.get("title")
        or normalized.get("step_id")
        or normalized.get("tool_name")
        or normalized.get("todo_id")
        or "task todo"
    ).strip()
    normalized["title"] = title
    return normalized


def _runtime_replan_normalized_checkpoint(
    checkpoint: Mapping[str, Any],
) -> dict[str, Any]:
    normalized = dict(checkpoint)
    title = str(
        normalized.get("title")
        or normalized.get("after_step_id")
        or normalized.get("checkpoint_id")
        or "task checkpoint"
    ).strip()
    normalized["title"] = title
    return normalized


def _runtime_workspace_item_summaries(items: Any) -> list[dict[str, Any]]:
    if not isinstance(items, list):
        return []
    summaries: list[dict[str, Any]] = []
    for item in items:
        if not isinstance(item, Mapping):
            continue
        summary = {
            "item_id": str(item.get("item_id") or "").strip(),
            "kind": str(item.get("kind") or "").strip(),
            "path": str(item.get("path") or "").strip(),
            "title": str(item.get("title") or "").strip(),
            "status": str(item.get("status") or "").strip(),
        }
        clean_summary = {
            key: value
            for key, value in summary.items()
            if value
        }
        if clean_summary:
            summaries.append(clean_summary)
    return summaries[:20]


def _runtime_workspace_item_key(item: Mapping[str, Any]) -> str:
    for key in ("item_id", "path", "title"):
        value = str(item.get(key) or "").strip()
        if value:
            return value
    return ""


def _selection_payload_with_timeline_fallback(
    selection_payload: Mapping[str, Any],
    timeline: list[dict[str, Any]],
) -> dict[str, Any]:
    payload = dict(selection_payload) if isinstance(selection_payload, Mapping) else {}
    if isinstance(payload.get("followup_target"), Mapping):
        return payload
    for event in reversed(timeline):
        if not isinstance(event, dict):
            continue
        if (
            _runtime_planner_base_event_type(str(event.get("event") or "").strip())
            != "agent.plan.selection"
        ):
            continue
        target = event.get("followup_target")
        if not isinstance(target, Mapping):
            continue
        event_payload = {
            str(key): value
            for key, value in event.items()
            if key not in {"event", "detail", "timestamp"}
        }
        return {**event_payload, **payload, "followup_target": dict(target)}
    return payload


def _tool_result_requests_replan(result: Mapping[str, Any]) -> bool:
    if not isinstance(result, Mapping):
        return False
    if result.get("approval_required") or result.get("blocked_by_user_goal"):
        return False
    if result.get("verification_failed") is True:
        return True
    if result.get("ok") is True:
        return False
    if result.get("ok") is False:
        return True
    if str(result.get("error") or "").strip():
        return True
    returncode = result.get("returncode")
    if returncode not in (None, "", 0, "0"):
        return True
    exit_code = result.get("exit_code")
    if exit_code not in (None, "", 0, "0"):
        return True
    return False


def _runtime_planner_completed_direct_requests_with_unavailable_replan(
    planned_tool_requests: Iterable[Mapping[str, Any]],
    replan_payloads: Iterable[Mapping[str, Any]],
    timeline: list[dict[str, Any]],
    *,
    tool_timeline_start: int,
) -> bool:
    if not _runtime_planner_replan_payloads_only_tool_unavailable(replan_payloads):
        return False
    requests = [request for request in planned_tool_requests if isinstance(request, Mapping)]
    primary_requests: list[Mapping[str, Any]] = []
    last_primary_index = -1
    for index, request in enumerate(requests):
        tool_name = str(request.get("tool") or "").strip()
        if not tool_name or tool_name not in _DIRECT_DAILY_DESKTOP_TOOLS:
            continue
        if tool_name in _DAILY_DESKTOP_DISCOVERY_TOOLS or tool_name in _DAILY_DESKTOP_VERIFY_TOOLS:
            continue
        primary_requests.append(request)
        last_primary_index = index
    if not primary_requests:
        return False
    if not all(
        _runtime_planner_tool_request_completed(
            request,
            timeline,
            tool_timeline_start=tool_timeline_start,
        )
        for request in primary_requests
    ):
        return False
    trailing_observation_tools = {
        str(request.get("tool") or "").strip()
        for request in requests[last_primary_index + 1 :]
        if str(request.get("tool") or "").strip() in {
            *_DAILY_DESKTOP_DISCOVERY_TOOLS,
            *_DAILY_DESKTOP_VERIFY_TOOLS,
        }
    }
    payloads = [payload for payload in replan_payloads if isinstance(payload, Mapping)]
    if not trailing_observation_tools:
        return bool(payloads) and all(
            _runtime_replan_payload_is_missing_desktop_observation(payload)
            and not _runtime_replan_payload_requires_continuation(payload)
            for payload in payloads
        )
    if not payloads:
        return False
    return all(
        any(tool in trailing_observation_tools for tool in _runtime_replan_payload_tool_candidates(payload))
        for payload in payloads
    )


def _runtime_planner_verified_app_open_before_unavailable_deferred_verification(
    planned_tool_requests: Iterable[Mapping[str, Any]],
    replan_payloads: Iterable[Mapping[str, Any]],
    timeline: list[dict[str, Any]],
    *,
    tool_timeline_start: int,
) -> tuple[list[dict[str, Any]], int] | None:
    raw_requests = list(planned_tool_requests)
    if not raw_requests or any(
        not isinstance(request, Mapping) for request in raw_requests
    ):
        return None
    requests = [request for request in raw_requests if isinstance(request, Mapping)]
    raw_payloads = list(replan_payloads)
    if (
        len(raw_payloads) != len(requests)
        or any(not isinstance(payload, Mapping) for payload in raw_payloads)
    ):
        return None
    payloads = [payload for payload in raw_payloads if isinstance(payload, Mapping)]
    if not payloads or any(
        str(payload.get("trigger") or "").strip() != "tool_unavailable"
        for payload in payloads
    ):
        return None

    expected_app_identities: list[str] = []
    for request in requests:
        tool_name = str(request.get("tool") or "").strip()
        request_input = (
            request.get("input")
            if isinstance(request.get("input"), Mapping)
            else None
        )
        app_name = (
            str(request_input.get("app_name") or "").strip()
            if isinstance(request_input, Mapping)
            else ""
        )
        app_identity = _strict_canonical_app_identity(app_name)
        if (
            request.get("continue_to_model") is not True
            or tool_name not in _DAILY_DESKTOP_VERIFY_TOOLS
            or not app_name
            or not app_identity
        ):
            return None
        expected_app_identities.append(app_identity)
    if not _runtime_planner_deferred_verifiers_have_distinct_unavailable_replans(
        requests,
        payloads,
    ):
        return None

    matched_primary_events: list[tuple[int, str, dict[str, Any]]] = []
    used_event_indexes: set[int] = set()
    timeline_end = min(tool_timeline_start, len(timeline))
    for expected_app_identity in expected_app_identities:
        matched_event: tuple[int, str, dict[str, Any], Mapping[str, Any]] | None = None
        for event_index in range(timeline_end - 1, -1, -1):
            if event_index in used_event_indexes:
                continue
            event = timeline[event_index]
            if str(event.get("event") or "").strip() != "agent.tool.call":
                continue
            event_tool = str(event.get("detail") or "").strip()
            if event_tool not in _RUNTIME_REPLAN_NO_REPEAT_AFTER_SUCCESS_TOOLS:
                continue
            event_input = (
                event.get("input_preview")
                if isinstance(event.get("input_preview"), Mapping)
                else {}
            )
            expected_event_app = str(event_input.get("app_name") or "").strip()
            if (
                not expected_event_app
                or _strict_canonical_app_identity(expected_event_app)
                != expected_app_identity
            ):
                continue
            result = event.get("result") if isinstance(event.get("result"), Mapping) else {}
            matched_event = (event_index, event_tool, dict(event_input), result)
            break
        if matched_event is None:
            return None
        event_index, event_tool, event_input, result = matched_event
        data = result.get("data") if isinstance(result.get("data"), Mapping) else {}
        observed_app = str(data.get("app_name") or "").strip()
        if (
            result.get("ok") is not True
            or data.get("launch_verified") is not True
            or not observed_app
            or _strict_canonical_app_identity(observed_app) != expected_app_identity
            or _strict_canonical_app_identity(
                str(event_input.get("app_name") or "")
            )
            != _strict_canonical_app_identity(observed_app)
        ):
            return None
        used_event_indexes.add(event_index)
        matched_primary_events.append((event_index, event_tool, event_input))
    matched_primary_events.sort(key=lambda item: item[0])
    return (
        [
            {
                "tool": event_tool,
                "input": event_input,
                "source": "runtime_planner",
                "planning_reason": "planner_verified_primary_postcondition",
            }
            for _event_index, event_tool, event_input in matched_primary_events
        ],
        matched_primary_events[0][0],
    )


def _strict_canonical_app_identity(value: str) -> str:
    compact = compact_app_alias(value)
    if not compact:
        return ""
    return _STRICT_CANONICAL_APP_IDENTITIES.get(compact, compact)


def _runtime_planner_deferred_verifiers_have_distinct_unavailable_replans(
    requests: list[Mapping[str, Any]],
    payloads: list[Mapping[str, Any]],
) -> bool:
    payload_to_request: dict[int, int] = {}

    def assign(request_index: int, visited_payloads: set[int]) -> bool:
        request = requests[request_index]
        for payload_index, payload in enumerate(payloads):
            if (
                payload_index in visited_payloads
                or not _runtime_planner_replan_matches_deferred_verifier(
                    request,
                    payload,
                )
            ):
                continue
            visited_payloads.add(payload_index)
            previous_request = payload_to_request.get(payload_index)
            if previous_request is None or assign(previous_request, visited_payloads):
                payload_to_request[payload_index] = request_index
                return True
        return False

    return all(assign(index, set()) for index in range(len(requests)))


def _runtime_planner_replan_matches_deferred_verifier(
    request: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> bool:
    metadata = (
        payload.get("metadata")
        if isinstance(payload.get("metadata"), Mapping)
        else {}
    )
    source_tool = str(
        payload.get("source_tool_name")
        or metadata.get("source_tool_name")
        or ""
    ).strip()
    if source_tool != str(request.get("tool") or "").strip():
        return False
    request_step_id = str(
        request.get("step_id") or request.get("planner_step_id") or ""
    ).strip()
    payload_step_id = str(
        payload.get("source_step_id") or payload.get("planner_step_id") or ""
    ).strip()
    if request_step_id and payload_step_id and request_step_id != payload_step_id:
        return False
    input_preview = (
        metadata.get("input_preview")
        if isinstance(metadata.get("input_preview"), Mapping)
        else payload.get("input_preview")
        if isinstance(payload.get("input_preview"), Mapping)
        else {}
    )
    payload_app_name = str(input_preview.get("app_name") or "").strip()
    if not payload_app_name:
        return True
    request_input = (
        request.get("input") if isinstance(request.get("input"), Mapping) else {}
    )
    return (
        _strict_canonical_app_identity(payload_app_name)
        == _strict_canonical_app_identity(
            str(request_input.get("app_name") or "")
        )
    )


def _runtime_replan_payload_is_missing_desktop_observation(payload: Mapping[str, Any]) -> bool:
    metadata = payload.get("metadata") if isinstance(payload.get("metadata"), Mapping) else {}
    capability_id = str(
        payload.get("target_capability_id")
        or payload.get("capability_id")
        or metadata.get("target_capability_id")
        or metadata.get("capability_id")
        or ""
    ).strip()
    if capability_id == "desktop.app_discovery":
        return True
    return any(
        tool in _DAILY_DESKTOP_DISCOVERY_TOOLS or tool in _DAILY_DESKTOP_VERIFY_TOOLS
        for tool in _runtime_replan_payload_tool_candidates(payload)
    )


def _runtime_planner_completed_direct_requests_with_verification_replan(
    planned_tool_requests: Iterable[Mapping[str, Any]],
    replan_payloads: Iterable[Mapping[str, Any]],
    timeline: list[dict[str, Any]],
    *,
    tool_timeline_start: int,
) -> bool:
    payloads: list[Mapping[str, Any]] = []
    for payload in replan_payloads:
        if not isinstance(payload, Mapping):
            continue
        nested_requests = (
            payload.get("replan_requests")
            if isinstance(payload.get("replan_requests"), list)
            else []
        )
        payloads.extend(item for item in nested_requests if isinstance(item, Mapping))
        if _runtime_replan_payload_tool_candidates(payload):
            payloads.append(payload)
    if not payloads:
        return False
    requests = [request for request in planned_tool_requests if isinstance(request, Mapping)]
    if any(bool(request.get("continue_to_model")) for request in requests):
        return False
    primary_requests: list[Mapping[str, Any]] = []
    last_primary_index = -1
    for index, request in enumerate(requests):
        tool_name = str(request.get("tool") or "").strip()
        if not tool_name or tool_name not in _DIRECT_DAILY_DESKTOP_TOOLS:
            continue
        if tool_name in _DAILY_DESKTOP_DISCOVERY_TOOLS or tool_name in _DAILY_DESKTOP_VERIFY_TOOLS:
            continue
        primary_requests.append(request)
        last_primary_index = index
    if last_primary_index < 0:
        return False
    if not any(
        _runtime_planner_tool_request_completed(
            request,
            timeline,
            tool_timeline_start=tool_timeline_start,
        )
        for request in primary_requests
    ):
        return False

    trailing_verification_tools = {
        str(request.get("tool") or "").strip()
        for request in requests[last_primary_index + 1 :]
        if str(request.get("tool") or "").strip() in _DAILY_DESKTOP_VERIFY_TOOLS
    }
    if not trailing_verification_tools:
        return False
    if all(
        _runtime_replan_payload_is_trailing_verification_failure(
            payload,
            trailing_verification_tools,
        )
        for payload in payloads
    ):
        return True
    if any(_runtime_replan_payload_requires_continuation(payload) for payload in payloads):
        return False
    return False


def _legacy_chat_direct_local_completed_with_verification_replan(
    planned_tool_requests: Iterable[Mapping[str, Any]],
    replan_payloads: Iterable[Mapping[str, Any]],
    timeline: list[dict[str, Any]],
    *,
    tool_timeline_start: int,
) -> bool:
    requests = [request for request in planned_tool_requests if isinstance(request, Mapping)]
    if not any(_request_uses_legacy_chat_direct_local_policy(request) for request in requests):
        return False
    primary_requests = [
        request
        for request in requests
        if str(request.get("tool") or "").strip() in _DIRECT_DAILY_DESKTOP_TOOLS
        and str(request.get("tool") or "").strip() not in _DAILY_DESKTOP_DISCOVERY_TOOLS
        and str(request.get("tool") or "").strip() not in _DAILY_DESKTOP_VERIFY_TOOLS
    ]
    if not primary_requests:
        return False
    if not all(
        _runtime_planner_tool_request_completed(
            request,
            timeline,
            tool_timeline_start=tool_timeline_start,
        )
        for request in primary_requests
    ):
        return False
    payloads = _flatten_runtime_replan_payloads(replan_payloads)
    if not payloads:
        return False
    return all(
        str(payload.get("trigger") or "").strip() == "verification_failed"
        for payload in payloads
    )


def _legacy_chat_direct_local_result_requests(
    planned_tool_requests: Iterable[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for request in planned_tool_requests:
        if not isinstance(request, Mapping):
            continue
        if not _request_uses_legacy_chat_direct_local_policy(request):
            continue
        tool_name = str(request.get("tool") or "").strip()
        if tool_name in _DAILY_DESKTOP_DISCOVERY_TOOLS:
            continue
        if tool_name in _DAILY_DESKTOP_VERIFY_TOOLS:
            continue
        result.append(dict(request))
    return _coalesced_legacy_chat_direct_local_result_requests(result)


def _coalesced_legacy_chat_direct_local_result_requests(
    planned_tool_requests: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    coalesced: list[dict[str, Any]] = []
    index = 0
    while index < len(planned_tool_requests):
        if index + 2 >= len(planned_tool_requests):
            coalesced.append(planned_tool_requests[index])
            index += 1
            continue
        open_request = planned_tool_requests[index]
        focus_request = planned_tool_requests[index + 1]
        type_request = planned_tool_requests[index + 2]
        open_input = open_request.get("input") if isinstance(open_request.get("input"), Mapping) else {}
        focus_input = focus_request.get("input") if isinstance(focus_request.get("input"), Mapping) else {}
        type_input = type_request.get("input") if isinstance(type_request.get("input"), Mapping) else {}
        app_name = str(open_input.get("app_name") or "").strip()
        text = str(type_input.get("text") or "").strip()
        if (
            str(open_request.get("tool") or "") in {"app.open", "desktop.open_app"}
            and str(focus_request.get("tool") or "") in {"app.focus", "desktop.focus_app"}
            and str(type_request.get("tool") or "") == "desktop.safe_type_text"
            and app_name
            and str(focus_input.get("app_name") or "").strip() == app_name
            and text
        ):
            coalesced.append(
                {
                    **type_request,
                    "tool": "app.open_and_safe_type_text",
                    "input": {"app_name": app_name, "text": text},
                }
            )
            index += 3
            continue
        coalesced.append(planned_tool_requests[index])
        index += 1
    return coalesced


def _request_uses_legacy_chat_direct_local_policy(request: Mapping[str, Any]) -> bool:
    policy = request.get("desktop_execution_policy")
    return (
        isinstance(policy, Mapping)
        and str(policy.get("source") or "").strip() == "legacy_chat_direct_local"
    )


def _flatten_runtime_replan_payloads(
    replan_payloads: Iterable[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    payloads: list[Mapping[str, Any]] = []
    for payload in replan_payloads:
        if not isinstance(payload, Mapping):
            continue
        nested_requests = (
            payload.get("replan_requests")
            if isinstance(payload.get("replan_requests"), list)
            else []
        )
        payloads.extend(item for item in nested_requests if isinstance(item, Mapping))
        if _runtime_replan_payload_tool_candidates(payload):
            payloads.append(payload)
    return payloads


